window.TADABBUR_MUDDATHTHIR = {"_meta":{"description":"تدبّر سورة المدّثّر (٧٤) — سورةٌ مكّيّةٌ من أوائلِ ما نزل. محورُها الأمرُ بالإنذارِ والقيامِ بأعباءِ الدعوة، وتهديدُ الوليدِ بنِ المغيرةِ الذي فكّر وقدّر وكذّب القرآن، ووصفُ سقرَ وخزنتِها التسعةَ عشرَ وحكمةِ عددهم، والقسمُ على أنّ النارَ إحدى الكبر، وأنّ كلَّ نفسٍ رهينةٌ بكسبها إلا أصحابَ اليمين، وحوارُ أهلِ الجنّةِ مع المجرمين في سببِ دخولهم سقر، والإنكارُ على المعرضين عن التذكرة. فيها «يا أيها المدثر * قم فأنذر»، و«وثيابك فطهر»، و«كل نفس بما كسبت رهينة»، و«ما سلككم في سقر * قالوا لم نك من المصلين»، و«كلا إنه تذكرة».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":74,"name":"المدثر","total_ayahs":56,"audio":["audio/074001.mp3","audio/074002.mp3","audio/074003.mp3","audio/074004.mp3","audio/074005.mp3","audio/074006.mp3","audio/074007.mp3","audio/074008.mp3","audio/074009.mp3","audio/074010.mp3"],"passages":[{"title":"الأمرُ بالإنذارِ والقيامِ بأعباءِ الدعوة","range":[1,7],"theme":"نداءُ النبيِّ «يا أيها المدثر» والأمرُ بالإنذار «قم فأنذر»، وبتعظيمِ الله «وربك فكبر»، وطهارةِ الظاهرِ والباطن «وثيابك فطهر»، وهجرِ الرجز «والرجز فاهجر»، وإخلاصِ العطاء «ولا تمنن تستكثر»، والصبرِ لله «ولربك فاصبر»","verses":[{"n":1,"reflection":{"text":"«يا أيها المدثر» — يا أيها المتغطّي بثيابه (النبيُّ ﷺ حين رجع يرجف بعد أوّلِ الوحي فتدثّر)؛ ففي هذا نداءُ الله لنبيّه بلطفٍ ثم تكليفِه بالإنذار؛ فتهيّأ لحملِ الرسالةِ ولا تركن إلى الدعة، فالنداءُ اللطيفُ يُتبَع بأمرِ الدعوة، فاستجب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستجابةُ لنداءِ الله والتهيّؤُ لحملِ الرسالة."},"action":{"text":"تأمّل نداءَ الله لنبيّه: يا أيها المدّثّر — أي يا أيها المتغطّي المتلفّف بثيابه؛ نُودِيَ النبيُّ ﷺ بهذا الوصفِ لحاله حين رجع من غارِ حراءَ يرجف فؤاده بعد رؤيةِ جبريلَ فقال: دثّروني دثّروني، فناداه الله بلطفٍ بما هو عليه، ثم كلّفه بالقيامِ للإنذار «يا أيها المدثر»؛ ففي هذا بيانُ لطفِ الله في ندائه لنبيّه بوصفِ حاله، ثم انتقالِه إلى التكليفِ العظيمِ بالدعوةِ والإنذار؛ فالنداءُ اللطيفُ مقدّمةُ التكليف؛ فتهيّأ أنت لحملِ ما كلّفك الله، واستجب لأمره، ولا تركن إلى الراحةِ والدعة؛ يا أيها المزّمّل قم الليل؛ يا أيها المدّثّر قم فأنذر؛ فالله ينادي عبده بلطفٍ ليكلّفه بما يرفعه؛ فاستجب لنداءِ الله، وتهيّأ لحملِ رسالته وأمانتها؛ فمن استجاب لله وحمل أمانته رُفِع، ومن تثاقل حُرِم؛ فاجعل الاستجابةَ لنداءِ الله والتهيّؤَ لحملِ الرسالةِ دأبك."}},{"n":2,"reflection":{"text":"«قم فأنذر» — قم من مضجعك فأنذر الناسَ عذابَ الله إن لم يؤمنوا؛ ففي هذا الأمرُ بالقيامِ للدعوةِ والإنذار؛ فقم بواجبِ الدعوةِ وأنذر من حولك، فالإنذارُ أوّلُ واجبِ الداعية، فقم به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"القيامُ بواجبِ الدعوةِ والإنذارِ لمن حولك."},"action":{"text":"تأمّل أمرَ الإنذار: قم — أي انهض من مضجعك بجدٍّ وعزم — فأنذر — أي حذّر الناسَ عذابَ الله وبأسه إن أقاموا على الكفرِ والمعصية، وبلّغهم ما أُرسِلتَ به «قم فأنذر»؛ ففي هذا بيانُ الأمرِ بالقيامِ لأعباءِ الدعوةِ والبدءِ بالإنذارِ والتحذير، فكان هذا أوّلَ ما أُمِر به من التبليغِ بعد اقرأ؛ فالإنذارُ أوّلُ واجباتِ الداعية؛ فقم أنت بواجبِ الدعوةِ إلى الله، وأنذر من حولك (أهلك ومن تبلغه دعوتك) عذابَ الله، وذكّرهم ولا تسكت عن بيانِ الحقّ؛ وأنذر عشيرتك الأقربين؛ يا أيها الرسولُ بلّغ ما أُنزِل إليك؛ فما على الرسولِ إلا البلاغ؛ فالقيامُ بالإنذارِ والدعوةِ واجبٌ على العالمِ بقدره؛ فقم به، وأنذر، وبلّغ الحقَّ بحكمة؛ فمن قام بالدعوةِ والإنذارِ أدّى الأمانة، ومن سكت عن البلاغِ أثم؛ فاجعل القيامَ بواجبِ الدعوةِ والإنذارِ دأبك."}},{"n":3,"reflection":{"text":"«وربك فكبر» — وربَّك وحده فعظّم وأفرِده بالتكبيرِ والإجلال؛ ففي هذا الأمرُ بتعظيمِ الله وتوحيدِه؛ فعظّم ربّك وكبّره وأفرِده بالإجلال، فتكبيرُ الله أساسُ الدعوةِ وروحُها، فكبّره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله وتكبيرُه وإفرادُه بالإجلال."},"action":{"text":"تأمّل أمرَ التكبير: وربَّك فكبّر — أي وربَّك وحده فعظّم، وأفرِده بالكبرياءِ والتعظيمِ والإجلال، ونزّهه عن الشركاءِ والأنداد، فهو الكبيرُ المتعال «وربك فكبر»؛ ففي هذا بيانُ الأمرِ بتعظيمِ الله وتكبيرِه وإفرادِه بالكبرياء، وهو أصلُ الدعوةِ وروحُها؛ فقُدِّم تعظيمُ الله على سائرِ الأوامرِ لأنه أساسُها؛ فتكبيرُ الله وتعظيمُه روحُ التوحيد؛ فعظّم أنت ربّك في قلبك ولسانك وعملك، وأفرِده بالكبرياءِ والإجلال، ولا تجعل معه كبيرًا سواه؛ الله أكبر؛ وقل الحمدُ لله الذي لم يتّخذ ولدًا ولم يكن له شريكٌ في الملكِ ولم يكن له وليٌّ من الذلِّ وكبّره تكبيرًا؛ فالكبرياءُ رداءُ الله؛ فعظّمه، وكبّره، وأجلّه، ولا تُعظِّم سواه تعظيمَ العبادة؛ فمن عظّم الله وكبّره وحّده وأجلّه، ومن أشرك أو استكبر خسر؛ فاجعل تعظيمَ الله وتكبيرَه وإفرادَه بالإجلالِ دأبك."}},{"n":4,"reflection":{"text":"«وثيابك فطهر» — وثيابك فطهّرها من النجاسات (وقيل: ونفسك فطهّرها من الذنوب، وعملك فأخلصه)؛ ففي هذا الأمرُ بطهارةِ الظاهرِ والباطن؛ فطهّر ثيابك وبدنك وقلبك من كلِّ دنس، فالطهارةُ ظاهرًا وباطنًا من الإيمان، فتطهّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طهارةُ الظاهرِ والباطنِ من كلِّ دنس."},"action":{"text":"تأمّل أمرَ التطهير: وثيابك فطهّر — أي طهّر ثيابك من النجاساتِ والأقذارِ استعدادًا للصلاةِ ولقاءِ الله، وقيل: طهّر نفسك وعملك من الذنوبِ والشركِ والأخلاقِ الدنيئة، فإنّ العربَ تكني بالثيابِ عن النفسِ والقلب، وقيل: قصّر ثيابك تنزّهًا عن الخيلاء «وثيابك فطهر»؛ ففي هذا بيانُ الأمرِ بالطهارةِ الحسّيّةِ (طهارةِ الثيابِ والبدن) والمعنويّةِ (طهارةِ القلبِ والعملِ من الشركِ والذنوبِ والأخلاقِ الرديئة)؛ فطهارةُ الظاهرِ والباطنِ من كمالِ الإيمان؛ فطهّر أنت ثيابك وبدنك من النجاسةِ للصلاة، وطهّر قلبك من الشركِ والحسدِ والكبرِ والرياء، وعملك من الفساد؛ إنّ الله يحبّ التوّابين ويحبّ المتطهّرين؛ قد أفلح من زكّاها؛ الطهورُ شطرُ الإيمان؛ فالطهارةُ ظاهرًا وباطنًا زينةُ المؤمنِ وسبيلُ قربه؛ فطهّر ثيابك وبدنك وقلبك وعملك؛ فمن تطهّر ظاهرًا وباطنًا زكا وقرُب، ومن تلطّخ بالأدناسِ بعُد؛ فاجعل طهارةَ الظاهرِ والباطنِ دأبك."}},{"n":5,"reflection":{"text":"«والرجز فاهجر» — والرجزَ (الأوثانَ والأصنامَ، أو العذابَ المؤدّي إليه، أو المعاصي) فاهجرها هجرًا دائمًا؛ ففي هذا الأمرُ بهجرِ الشركِ والمعاصي؛ فاهجر كلَّ ما يُغضِب الله من شركٍ ومعصية، فهجرُ الرجزِ سبيلُ الطهارة، فاهجره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"هجرُ الشركِ والمعاصي وكلِّ ما يُغضِب الله."},"action":{"text":"تأمّل أمرَ هجرِ الرجز: والرجزَ فاهجر — أي اهجر الرجزَ هجرًا مستمرًّا؛ والرجزُ: الأوثانُ والأصنامُ التي تُعبَد من دونِ الله (فاهجر عبادتها والقربَ منها)، وقيل: العذابُ، أي اهجر ما يؤدّي إلى العذابِ من الأعمال، وقيل: المعاصي كلُّها «والرجز فاهجر»؛ ففي هذا بيانُ الأمرِ بهجرِ الشركِ والأوثانِ والمعاصي وكلِّ ما يُغضِب الله ويؤدّي إلى عذابه، هجرًا دائمًا لا رجعةَ فيه؛ فهجرُ الرجزِ (الشركِ والمعصية) شرطُ الطهارةِ والقرب؛ فاهجر أنت الشركَ وأهله، والمعاصيَ وأسبابها، وكلَّ ما يُسخِط ربّك، ولا تقربها؛ فاجتنبوا الرجسَ من الأوثانِ واجتنبوا قولَ الزور؛ وذروا ظاهرَ الإثمِ وباطنه؛ قل إنّ صلاتي ونسكي لله؛ فهجرُ الرجزِ (الشركِ والمعاصي) تمامُ التطهير؛ فاهجرها، واجتنبها، ولا تعد إليها؛ فمن هجر الرجزَ طهُر وقرُب، ومن قارفه تلطّخ وبعُد؛ فاجعل هجرَ الشركِ والمعاصي وكلِّ ما يُغضِب الله دأبك."}},{"n":6,"reflection":{"text":"«ولا تمنن تستكثر» — ولا تُعطِ عطاءً تطلب به أكثرَ منه (أو لا تمنُن بعملك مستكثرًا له على ربّك)؛ ففي هذا الأمرُ بإخلاصِ العطاءِ والعملِ من طلبِ الجزاءِ الدنيويِّ والمنّة؛ فأعطِ وأعمل لله لا لتستكثر عوضًا، فالإخلاصُ يُفسِده استكثارُ العملِ والمنّ، فأخلص.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العطاءِ والعملِ لله، وتركُ المنِّ والاستكثار."},"action":{"text":"تأمّل أمرَ الإخلاص: ولا تمنن تستكثر — أي لا تُعطِ العطيّةَ تلتمس بها أكثرَ منها من الناس (فتكون معاوضةً دنيويّةً لا صدقةً خالصة)، وقيل: لا تمنُن على ربّك بعملك مستكثرًا له مستعظمًا إيّاه، بل استقلّه في جنبِ نعمِ الله، وقيل: لا تمنن بالنبوّةِ والتبليغِ على الناسِ تطلب أجرًا «ولا تمنن تستكثر»؛ ففي هذا بيانُ الأمرِ بإخلاصِ العطاءِ والعملِ لله، وتركِ المنِّ به واستكثارِه واستعظامِه، فإنّ المنَّ والاستكثارَ يُحبِط العمل؛ فالإخلاصُ يُفسِده استكثارُ العملِ والمنُّ به؛ فأعطِ أنت وأعمل لله وحده لا لتستكثر عوضًا من الناس، ولا تمنُن بما تعمل ولا تستعظمه، بل استقلّه واحتقره في جنبِ حقِّ الله ونعمه؛ لا تُبطِلوا صدقاتكم بالمنِّ والأذى؛ يمنّون عليك أن أسلموا قل لا تمنّوا عليّ إسلامكم؛ وما لأحدٍ عنده من نعمةٍ تُجزى إلا ابتغاءَ وجهِ ربّه الأعلى؛ فالعطاءُ والعملُ الخالصُ ما خلا من المنِّ والاستكثار؛ فأخلص، ولا تمنُن، ولا تستكثر عملك؛ فمن أخلص وترك المنَّ زكا عمله، ومن منّ واستكثر حبط؛ فاجعل إخلاصَ العطاءِ والعملِ وتركَ المنِّ والاستكثارِ دأبك."}},{"n":7,"reflection":{"text":"«ولربك فاصبر» — ولأجلِ ربّك وابتغاءَ وجهه فاصبر على أذى المكذّبين وأعباءِ الدعوةِ وأوامرِ الشرع؛ ففي هذا الأمرُ بالصبرِ لله؛ فاصبر على الطاعةِ وعن المعصيةِ وعلى الأذى محتسبًا لله، فالصبرُ لله زادُ الداعيةِ وعدّته، فاصبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ لله على الطاعةِ والأذى، واحتسابُه عند الله."},"action":{"text":"تأمّل أمرَ الصبر: ولربّك فاصبر — أي ولأجلِ ربّك وابتغاءَ وجهه ورضاه فاصبر: اصبر على القيامِ بأعباءِ الدعوةِ والإنذار، واصبر على أذى المكذّبين، واصبر على أوامرِ الشرعِ ونواهيه، واصبر على أقدارِ الله المؤلمة؛ فليكن صبرك خالصًا لله لا لحظِّ نفسٍ ولا رياء «ولربك فاصبر»؛ ففي هذا بيانُ الأمرِ بالصبرِ لله، وأنّ الداعيةَ يحتاج إلى صبرٍ عظيمٍ على ما يلقاه، وأنّ الصبرَ لا يكمل إلا إذا كان لله؛ فالصبرُ لله زادُ الداعيةِ وعُدّته؛ فاصبر أنت لله على طاعته وعن معصيته وعلى ما يصيبك من أذًى وبلاء، محتسبًا الأجرَ عنده، غيرَ جازعٍ ولا شاكٍّ؛ واصبر وما صبرك إلا بالله؛ فاصبر لحكم ربّك ولا تكن كصاحبِ الحوت؛ إنما يوفّى الصابرون أجرهم بغيرِ حساب؛ فالصبرُ لله سبيلُ النصرِ والأجرِ والتمكين؛ فاصبر، واحتسب، ولا تجزع؛ فمن صبر لله ظفر وأُجِر، ومن جزع خسر الأجرَ والمقصود؛ فاجعل الصبرَ لله على الطاعةِ والأذى واحتسابَه دأبك."}}]},{"title":"النفخُ في الناقورِ ويومُ العسير","range":[8,10],"theme":"النفخُ في الصور «فإذا نقر في الناقور»، وأنّ ذلك «يوم عسير على الكافرين غير يسير»","verses":[{"n":8,"reflection":{"text":"«فإذا نقر في الناقور» — فإذا نُفِخ في الصورِ (النفخةِ الثانيةِ للبعث)؛ ففي هذا بيانُ قربِ الساعةِ وحتمِ البعث؛ فاستعدّ لنفخةِ الصورِ التي يقوم بعدها الحساب، فالنفخُ في الناقورِ إيذانٌ بيومِ الجزاء، فاستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للبعثِ وقيامِ الساعة."},"action":{"text":"تأمّل نفخةَ الناقور: فإذا نُقِر في الناقور — أي فإذا نُفِخ في الصور (والناقورُ: الصور الذي يُنفَخ فيه للبعث)، وهي النفخةُ الثانيةُ التي يقوم بها الناسُ من قبورهم للحساب «فإذا نقر في الناقور»؛ ففي هذا بيانُ حتمِ البعثِ وقيامِ الساعة، وأنّ النفخَ في الصورِ إيذانٌ ببدءِ أهوالِ يومِ القيامةِ والحساب؛ فالبعثُ حقٌّ واقعٌ عند النفخِ في الصور؛ فاستعدّ أنت لذلك اليوم، وأيقن بالبعثِ، واعمل لِما بعد النفخة، فإنها فجأةٌ لا استئخارَ بعدها؛ ونُفِخ في الصورِ فإذا هم من الأجداثِ إلى ربّهم ينسلون؛ يوم يُنفَخ في الصورِ فتأتون أفواجًا؛ وما أمرُ الساعةِ إلا كلمحِ البصر؛ فالنفخُ في الناقورِ بدءُ يومِ الجزاء؛ فاستعدّ له، وأيقن بالبعث، وقدّم لنفسك؛ فمن استعدّ للبعثِ أمِن، ومن غفل عنه فوجئ بأهواله؛ فاجعل الاستعدادَ للبعثِ وقيامِ الساعةِ دأبك."}},{"n":9,"reflection":{"text":"«فذلك يومئذ يوم عسير» — فذلك اليومُ يومٌ عسيرٌ شديدُ الصعوبةِ والهول؛ ففي هذا بيانُ عسرِ يومِ القيامة؛ فاعمل لتيسيرِ حسابك في يومٍ عسير، فيومُ القيامةِ عسيرٌ فلا يُيسَّر إلا بالإيمانِ والعمل، فاستعدّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ عسرِ يومِ القيامةِ والعملُ لتيسيرِ الحساب."},"action":{"text":"تأمّل عسرَ ذلك اليوم: فذلك يومئذٍ — أي يومَ النفخِ في الصور — يومٌ عسيرٌ — أي شديدُ الصعوبةِ والشدّةِ والهولِ على الخلق، لِما فيه من الأهوالِ والحسابِ والجزاء «فذلك يومئذ يوم عسير»؛ ففي هذا بيانُ عسرِ يومِ القيامةِ وشدّته، وأنه لا ييسَّر إلا على من يسّره الله عليه بالإيمانِ والعملِ الصالح؛ فيومُ القيامةِ عسيرٌ في نفسه؛ فاعمل أنت لتيسيرِ حسابك في ذلك اليوم العسير، بالإيمانِ والتقوى والعملِ الصالحِ والتوبة؛ فذلك يومئذٍ يومٌ عسير على الكافرين غيرُ يسير؛ يوم يقوم الناسُ لربِّ العالمين؛ يومًا يجعل الولدانَ شيبًا؛ فيومُ القيامةِ عسيرٌ شديد، وتيسيرُه بالإيمانِ والعمل؛ فاستعدّ، واعمل، وسل الله أن ييسّر عليك حسابك؛ فمن عمل صالحًا يُسِّر عليه، ومن كذّب وأعرض عسُر عليه؛ فاجعل استحضارَ عسرِ يومِ القيامةِ والعملَ لتيسيرِ الحسابِ دأبك."}},{"n":10,"reflection":{"text":"«على الكافرين غير يسير» — هو على الكافرين غيرُ سهلٍ ولا هيّن (بل عسيرٌ عليهم خاصّة)؛ ففي هذا بيانُ أنّ عسرَ ذلك اليومِ يشتدّ على الكافرين، وييسَّر على المؤمنين؛ فآمن واعمل لتكون من الميسَّرِ عليهم، فعسرُ القيامةِ خاصٌّ بالكافرين، فآمن لتُيَسَّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ ليكون الحسابُ يسيرًا، والحذرُ من عسرِ يومِ الكافرين."},"action":{"text":"تأمّل خصوصيّةَ العسر: على الكافرين — أي ذلك اليومُ العسيرُ يشتدّ ويعظم عسرُه على الكافرين خاصّة — غيرُ يسير — أي ليس بسهلٍ ولا هيّنٍ عليهم، بل هو في غايةِ الشدّةِ والصعوبةِ عليهم، بخلافِ المؤمنين الذين ييسَّر عليهم الحساب «على الكافرين غير يسير»؛ ففي هذا بيانُ أنّ عسرَ يومِ القيامةِ إنما يشتدّ على الكافرين، وأنّ المؤمنَ ييسَّر عليه بقدرِ إيمانه وعمله، فيكون اليومُ يسيرًا على أهلِ الإيمان؛ فعسرُ ذلك اليومِ خاصٌّ بالكافرين؛ فآمن أنت واعمل صالحًا لتكون من الذين ييسَّر عليهم الحساب، ولا تكن من الكافرين الذين يعسُر عليهم؛ فأمّا من أوتي كتابه بيمينه فسوف يُحاسَب حسابًا يسيرًا؛ يومئذٍ لا تنفع الشفاعةُ إلا من أذن له الرحمن؛ فذلك يومئذٍ يومٌ عسير على الكافرين غيرُ يسير؛ فالعسرُ في القيامةِ على الكافرين، واليسرُ للمؤمنين؛ فآمن، واعمل، واحذر سبيلَ الكافرين؛ فمن آمن وعمل يُسِّر عليه، ومن كفر عسُر يومه؛ فاجعل الإيمانَ والعملَ ليُيسَّر حسابك والحذرَ من عسرِ يومِ الكافرين دأبك."}}]},{"title":"تهديدُ الوليدِ الذي فكّر وقدّر وكذّب القرآنَ ووصفُ سقر","range":[11,30],"theme":"وعيدُ المنعَمِ عليه الذي كفر «ذرني ومن خلقت وحيدا وجعلت له مالا ممدودا وبنين شهودا ومهدت له تمهيدا ثم يطمع أن أزيد»، وأنّ سببَ حرمانه العنادُ «كلا إنه كان لآياتنا عنيدا سأرهقه صعودا»، وتصويرُ تكلّفِه في ردِّ الحقّ «إنه فكر وقدر فقتل كيف قدر... ثم نظر ثم عبس وبسر ثم أدبر واستكبر»، وفريتِه «إن هذا إلا سحر يؤثر إن هذا إلا قول البشر»، وجزائِه «سأصليه سقر»، ووصفِ سقر «لا تبقي ولا تذر لواحة للبشر عليها تسعة عشر»","verses":[{"n":11,"reflection":{"text":"«ذرني ومن خلقت وحيدا» — دعني — يا محمد — ومن خلقته وحيدًا فريدًا لا مالَ له ولا ولد (الوليدَ بنَ المغيرة)، فأنا أكفيكه؛ ففي هذا وعيدٌ لمن كفر بعد النعمة؛ فكِل أمرَ من عاندك إلى الله، فالله كافٍ من طغى بعد نعمته، فوكّل أمره إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ أمرِ المعاندِ إلى الله، واستحضارُ أنّ الخلقَ والنعمةَ منه."},"action":{"text":"تأمّل الوعيدَ للمعاند: ذرني — أي دعني وإيّاه، وكِل أمره إليّ فأنا أكفيكه وأنتقم منه — ومن خلقتُ وحيدًا — أي الذي خلقته منفردًا لا مالَ معه ولا ولدَ ولا جاه، ثم أنعمت عليه، وهو الوليدُ بنُ المغيرةِ المخزوميُّ الذي كذّب القرآنَ بعد أن كاد يؤمن «ذرني ومن خلقت وحيدا»؛ ففي هذا بيانُ وعيدِ الله لهذا المعاندِ الذي خلقه الله وحيدًا فقيرًا ثم أغناه فكفر، وتسليةِ النبيِّ بأنّ الله كافيه؛ فالله كافٍ من عاند وطغى بعد نعمته؛ فكِل أنت أمرَ من عاندك وكذّبك إلى الله، واستحضر أنّ الخلقَ والرزقَ والنعمَ كلَّها منه وحده، وأنه القادرُ على الأخذ؛ وذرني والمكذّبين أولي النعمة؛ فذرني ومن يكذّب بهذا الحديث؛ ولا تطع كلَّ حلّافٍ مهين؛ فالله يتولّى أمرَ من عاند رسله، والنعمُ منه فمن كفرها أُخِذ؛ ففوّض أمرَ خصومك إليه، واشكر نعمه، ولا تكفرها؛ فمن فوّض أمره لله وشكر كُفِيَ، ومن طغى بالنعمةِ أُخِذ؛ فاجعل تفويضَ أمرِ المعاندِ إلى الله واستحضارَ أنّ النعمةَ منه دأبك."}},{"n":12,"reflection":{"text":"«وجعلت له مالا ممدودا» — وجعلتُ له مالًا واسعًا ممتدًّا كثيرًا؛ ففي هذا بيانُ عظمِ نعمةِ الله على هذا الكافرِ التي قابلها بالكفر؛ فاشكر مالك ولا تكفر نعمةَ الله فيه، فالمالُ نعمةٌ تُوجِب الشكرَ لا الطغيان، فاشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ المالِ وعدمُ الطغيانِ بها."},"action":{"text":"تأمّل نعمةَ المالِ الممدود: وجعلتُ له مالًا ممدودًا — أي مالًا كثيرًا واسعًا ممتدًّا متتابعًا من زروعٍ وضروعٍ وتجارةٍ ونقدٍ لا ينقطع؛ فقد أنعم الله على الوليدِ بمالٍ عظيم «وجعلت له مالا ممدودا»؛ ففي هذا بيانُ عظمِ نعمةِ الله على هذا الكافرِ بالمالِ الواسع، وأنه قابل هذه النعمةَ بالكفرِ والعناد؛ فالمالُ نعمةٌ من الله تستوجب الشكرَ لا الطغيان؛ فاشكر أنت نعمةَ الله عليك في مالك وأنفِقه في طاعته، ولا تكفر النعمةَ ولا تطغَ بها؛ وآتاكم من كلِّ ما سألتموه وإن تعدّوا نعمةَ الله لا تُحصوها؛ إنّ الإنسانَ ليطغى أن رآه استغنى؛ لئن شكرتم لأزيدنّكم؛ فالمالُ نعمةٌ تُوجِب الشكرَ، والطغيانُ بها كفرٌ يُوجِب الأخذ؛ فاشكر مالك، وأنفِقه في الخير، ولا تطغَ به؛ فمن شكر نعمةَ المالِ بورك له، ومن كفرها وطغى أُخِذ؛ فاجعل شكرَ نعمةِ المالِ وعدمَ الطغيانِ بها دأبك."}},{"n":13,"reflection":{"text":"«وبنين شهودا» — وبنينَ حضورًا معه في مجلسه لا يغيبون عنه في تجارةٍ ولا سفر؛ ففي هذا بيانُ تمامِ نعمةِ الله على هذا الكافرِ بالولد؛ فاشكر نعمةَ الولدِ ولا تجعلها سببَ غفلة، فالبنون نعمةٌ تُوجِب الشكرَ لا الاغترار، فاشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الولدِ وعدمُ الاغترارِ بها."},"action":{"text":"تأمّل نعمةَ البنين: وبنينَ شهودًا — أي أولادًا حضورًا معه في مكّةَ لا يغيبون عنه، يشهدون معه المجالسَ والمحافل، وكانوا عشرةً أو ثلاثةَ عشر، أغنياءَ لا يحتاجون إلى السفرِ للتجارة لكثرةِ مالِ أبيهم «وبنين شهودا»؛ ففي هذا بيانُ تمامِ نعمةِ الله على الوليدِ بالبنينِ الحاضرين، وأنه مع ذلك كفر وعاند؛ فالبنون نعمةٌ من الله تستوجب الشكر؛ فاشكر أنت نعمةَ الله عليك في ولدك، وربّهم على الخير، ولا تجعل النعمةَ سببَ اغترارٍ وغفلةٍ عن الله؛ المالُ والبنون زينةُ الحياةِ الدنيا والباقياتُ الصالحاتُ خيرٌ عند ربّك؛ إنما أموالكم وأولادكم فتنة؛ زُيِّن للناسِ حبُّ الشهواتِ من النساءِ والبنين؛ فالبنون نعمةٌ وزينةٌ وفتنة، وشكرها بطاعةِ الله وتربيتهم على الخير؛ فاشكرها، ولا تغترّ بها، ولا تُلهِك عن ربّك؛ فمن شكر نعمةَ الولدِ ولم يغترّ نفعه، ومن اغترّ بها وغفل خسر؛ فاجعل شكرَ نعمةِ الولدِ وعدمَ الاغترارِ بها دأبك."}},{"n":14,"reflection":{"text":"«ومهدت له تمهيدا» — وبسطتُ له في العيشِ والجاهِ والرياسةِ بسطًا، ويسّرتُ له أسبابَ الحياةِ تيسيرًا؛ ففي هذا بيانُ إسباغِ الله نعمَه على هذا الكافر؛ فاشكر ما مهّد الله لك من عيش، فتمهيدُ العيشِ نعمةٌ تُوجِب الشكر، فاشكر ولا تكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ ما مهّد الله من العيشِ والجاه، وعدمُ كفرِ النعمة."},"action":{"text":"تأمّل تمهيدَ العيش: ومهّدتُ له تمهيدًا — أي بسطتُ له في الرياسةِ والجاهِ والذكرِ والعيشِ الرغيدِ بسطًا، ويسّرتُ له أمورَ الدنيا تيسيرًا، فكان مذكورًا مُعظَّمًا بين قومه، مبسوطًا له في كلِّ ما يريد «ومهدت له تمهيدا»؛ ففي هذا بيانُ إسباغِ الله نعمَه الظاهرةَ والباطنةَ على الوليد: المالِ والولدِ والجاهِ والرياسةِ والعيشِ الممهَّد، ثم كفرِه بعد ذلك كلِّه؛ فتمهيدُ العيشِ والجاهِ نعمةٌ من الله تستوجب الشكر؛ فاشكر أنت ما مهّد الله لك من عيشٍ وجاهٍ وعافيةٍ وأمن، ووظّفه في طاعته، ولا تكفر نعمته ولا تطغَ بها؛ ألم نجعل له عينين ولسانًا وشفتين وهديناه النجدين؛ وأسبغ عليكم نعمه ظاهرةً وباطنة؛ فمن يعمل من الصالحات فلا كفرانَ لسعيه؛ فتمهيدُ الله للعبدِ في عيشه نعمةٌ تُوجِب شكرًا لا كفرًا؛ فاشكرها، ووظّفها في طاعته، ولا تطغَ؛ فمن شكر ما مُهِّد له بورك، ومن كفره أُخِذ؛ فاجعل شكرَ ما مهّد الله من العيشِ وعدمَ كفرِ النعمةِ دأبك."}},{"n":15,"reflection":{"text":"«ثم يطمع أن أزيد» — ثم مع كفرِه بعد كلِّ هذه النعمِ يطمع أن أزيده مالًا وولدًا وجاهًا؛ ففي هذا بيانُ قبحِ طمعِ الكافرِ في المزيدِ مع كفرِه، وأنّ الزيادةَ بالشكرِ لا بالكفر؛ فاطلب الزيادةَ بالشكرِ لا بالطمعِ مع الكفر، فالمزيدُ للشاكرين لا للكافرين، فاشكر لتُزاد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الزيادةِ بالشكرِ لا بالكفر، وذمُّ الطمعِ مع العناد."},"action":{"text":"تأمّل قبحَ طمعِه: ثم يطمع — أي ثم مع كفرِه وعنادِه بعد إنعامي عليه بكلِّ ذلك — أن أزيدَ — أي يطمع أن أزيده من المالِ والولدِ والجاه، ويرجو دوامَ النعمةِ والزيادةَ فيها مع كفرانِه لها «ثم يطمع أن أزيد»؛ ففي هذا بيانُ قبحِ حالِ هذا الكافر: يكفر النعمةَ ثم يطمع في المزيد، وذلك محال، فإنّ الزيادةَ إنما تكون بالشكرِ لا بالكفر؛ فالمزيدُ للشاكرين، والكفرُ سبيلُ زوالِ النعمةِ لا زيادتها؛ فاطلب أنت الزيادةَ من الله بشكرِ نعمه لا بالطمعِ مع الكفرِ والعناد، فمن شكر زِيد، ومن كفر سُلِبَ؛ لئن شكرتم لأزيدنّكم ولئن كفرتم إنّ عذابي لشديد؛ أيحسبون أنما نمدّهم به من مالٍ وبنين نسارع لهم في الخيرات؛ فالزيادةُ ثمرةُ الشكر، والطمعُ فيها مع الكفرِ حمقٌ ومحال؛ فاشكر لتُزاد، ولا تطمع في المزيدِ وأنت كافرٌ بالنعمة؛ فمن شكر زِيد، ومن كفر وطمع خُيِّب؛ فاجعل طلبَ الزيادةِ بالشكرِ لا بالكفرِ دأبك."}},{"n":16,"reflection":{"text":"«كلا إنه كان لآياتنا عنيدا» — حقًّا لن يُزاد، إنه كان لآياتِنا (القرآنِ والحقِّ) معانِدًا جاحدًا مكابرًا؛ ففي هذا بيانُ أنّ سببَ حرمانِه العنادُ لآياتِ الله؛ فاحذر العنادَ لآياتِ الله فإنه سببُ الحرمانِ والعذاب، فالمعاندُ للحقِّ محرومٌ معذّب، فاذعن للحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإذعانُ لآياتِ الله، والحذرُ من العنادِ والمكابرة."},"action":{"text":"تأمّل عاقبةَ العناد: كلّا — أي حقًّا وردعًا له عن طمعه، لن يُزاد ولن يُعطى ما يطمع فيه — إنه كان لآياتِنا عنيدًا — أي كان معانِدًا جاحدًا مكابِرًا لآياتِنا (القرآنِ والحقّ)، يعرفها ثم يجحدها عنادًا واستكبارًا لا جهلًا «كلا إنه كان لآياتنا عنيدا»؛ ففي هذا بيانُ أنّ سببَ حرمانِ هذا الكافرِ من الخيرِ والزيادةِ هو عنادُه لآياتِ الله ومكابرتُه للحقِّ بعد معرفته؛ فالعنادُ للحقِّ سببُ الحرمانِ والطردِ والعذاب؛ فاحذر أنت العنادَ لآياتِ الله والمكابرةَ عن الحقِّ بعد وضوحه، وأذعِن للحقِّ متى تبيّن لك، ولا تجحده كبرًا؛ وجحدوا بها واستيقنتها أنفسهم ظلمًا وعلوًّا؛ ثمّ يصرّ مستكبرًا كأن لم يسمعها؛ إنه فكّر وقدّر؛ فالعنادُ للحقِّ بعد معرفته أقبحُ الكفرِ وأسببُه للعذاب؛ فأذعِن للحقّ، ولا تعاند، ولا تكابر؛ فمن أذعن للحقِّ اهتدى، ومن عاند وكابر حُرِم وعُذِّب؛ فاجعل الإذعانَ لآياتِ الله والحذرَ من العنادِ دأبك."}},{"n":17,"reflection":{"text":"«سأرهقه صعودا» — سأكلّفه عذابًا شاقًّا مُتعِبًا لا يطيقه (وقيل: جبلًا في النارِ يُصعِده ثم يتردّى)؛ ففي هذا بيانُ عاقبةِ العنادِ: العذابُ الشاقّ؛ فاحذر أن يُرهِقك عنادُك عذابًا صعدًا، فعاقبةُ المعاندِ عذابٌ لا يُطاق، فاتّقِ سبيله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عاقبةِ العنادِ: العذابِ الشاقِّ الذي لا يُطاق."},"action":{"text":"تأمّل جزاءَ العناد: سأُرهِقه — أي سأكلّفه وأُحمِّله وأُغشِيه — صعودًا — أي عذابًا شاقًّا مُتعِبًا لا يطيقه ولا يقدر عليه، وقيل: هو جبلٌ من نارٍ في جهنّم يُكلَّف صعودَه فكلّما وضع يده ذابت ثم تعود، يتصاعد فيه أبدًا في مشقّةٍ لا تنقطع «سأرهقه صعودا»؛ ففي هذا بيانُ عاقبةِ عنادِ هذا الكافرِ لآياتِ الله: عذابٌ شاقٌّ متزايدٌ لا يُطاق؛ فعاقبةُ المعاندِ للحقِّ عذابٌ صعدٌ لا راحةَ فيه؛ فاحذر أنت أن يُرهِقك عنادُك أو معصيتك عذابًا صعدًا، واتّقِ الله لئلّا تسلك سبيلَ المعاندين؛ ومن يعرض عن ذكرِ ربّه يسلكه عذابًا صعدًا؛ إنّ لدينا أنكالًا وجحيمًا؛ سأصليه سقر؛ فعنادُ الحقِّ يُورِد العذابَ الشاقَّ الذي لا يُطاق؛ فاتّقِ سبيلَ المعاندين، وأذعِن للحقّ، واعمل صالحًا؛ فمن أذعن للحقِّ نجا، ومن عاند أُرهِق صعودًا؛ فاجعل الحذرَ من عاقبةِ العنادِ دأبك."}},{"n":18,"reflection":{"text":"«إنه فكر وقدر» — إنه فكّر في القرآنِ ماذا يقول فيه ليصدّ الناسَ عنه، وقدّر في نفسه ما يقول؛ ففي هذا بيانُ تكلّفِ الكافرِ في ردِّ الحقِّ بعد تفكيرٍ وتدبير؛ فاحذر أن تُعمِل فكرك في ردِّ الحقِّ، بل أعمِله في قبوله، فتسخيرُ الفكرِ لردِّ الحقِّ مهلكة، فأعمِل عقلك في الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توظيفُ الفكرِ في قبولِ الحقِّ لا في ردِّه."},"action":{"text":"تأمّل تكلّفَه في ردِّ الحقّ: إنه فكّر — أي أعمل فكره وروّى في نفسه ماذا يقول في القرآنِ ليصرف الناسَ عنه في الموسم — وقدّر — أي هيّأ في نفسه قولًا ورتّبه ودبّره، لمّا سألته قريشٌ أن يقول في القرآنِ قولًا يُنفّر عنه «إنه فكر وقدر»؛ ففي هذا بيانُ تكلّفِ الكافرِ وإعمالِه فكره وعقله في ردِّ الحقِّ والصدِّ عنه، بدل أن يُعمِله في قبوله واتّباعه؛ فمن سخّر عقله لردِّ الحقِّ هلك؛ فاحذر أنت أن تُعمِل فكرك وذكاءك في ردِّ الحقِّ والتحيّلِ على دفعه، بل أعمِله في تدبّرِ الحقِّ وقبوله واتّباعه؛ أفلا يتدبّرون القرآن؛ إنّ في خلقِ السماواتِ والأرضِ لآياتٍ لأولي الألباب؛ فقالوا سمعنا وأطعنا؛ فالعقلُ نعمةٌ يُهلِك صاحبَه إن سخّره لردِّ الحقّ، ويُنجيه إن سخّره لقبوله؛ فأعمِل فكرك في الحقِّ لتتّبعه، لا في ردّه لتهلك؛ فمن وظّف عقله في قبولِ الحقِّ اهتدى، ومن وظّفه في ردّه ضلّ؛ فاجعل توظيفَ الفكرِ في قبولِ الحقِّ دأبك."}},{"n":19,"reflection":{"text":"«فقتل كيف قدر» — فلُعِن وعُذِّب، كيف قدّر ودبّر هذا التقديرَ الباطلَ في ردِّ الحقّ؟ ففي هذا دعاءٌ عليه وتعجّبٌ من سوءِ تقديره؛ فاحذر أن تُدبّر تدبيرًا في معصيةِ الله، فتدبيرُ الباطلِ يُوجِب اللعنة، فاجعل تدبيرك في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تدبيرِ الباطل، وتوجيهُ التدبيرِ للحقّ."},"action":{"text":"تأمّل الدعاءَ عليه: فقُتِل — أي لُعِن وعُذِّب وأُهلِك، دعاءٌ عليه بأشنعِ الدعاء — كيف قدّر — أي تعجّبٌ من سوءِ ما قدّره ودبّره في نفسه من ردِّ الحقِّ والطعنِ في القرآن، كيف اهتدى فكره إلى هذا الباطلِ الشنيع «فقتل كيف قدر»؛ ففي هذا بيانُ الدعاءِ على هذا الكافرِ باللعنِ والهلاك، والتعجّبِ من سوءِ تقديره وتدبيره في ردِّ الحقّ؛ فتدبيرُ الباطلِ ومقارعةُ الحقِّ يُوجِب اللعنةَ والعذاب؛ فاحذر أنت أن تُدبّر تدبيرًا أو تُعمِل حيلةً في معصيةِ الله أو ردِّ حقٍّ أو ظلمِ خلق، فإنّ مكرَ السيّئِ لا يحيق إلا بأهله؛ ولا يحيق المكرُ السيّئُ إلا بأهله؛ وقد مكروا مكرهم وعند الله مكرهم؛ فتدبيرُ الباطلِ يرتدّ على صاحبه لعنةً وخسارًا؛ فوجّه تدبيرك وذكاءك إلى الحقِّ والخير، لا إلى الباطلِ والشرّ؛ فمن دبّر في الحقِّ أفلح، ومن دبّر في الباطلِ لُعِن؛ فاجعل الحذرَ من تدبيرِ الباطلِ وتوجيهَ التدبيرِ للحقِّ دأبك."}},{"n":20,"reflection":{"text":"«ثم قتل كيف قدر» — ثم لُعِن مرّةً أخرى تأكيدًا، كيف قدّر ذلك التقديرَ الباطل؟ ففي هذا تكريرُ الدعاءِ عليه تأكيدًا لعظمِ جرمه؛ فاعلم أنّ ردَّ الحقِّ عن تدبيرٍ جريمةٌ يُضاعَف عليها الوعيد، فتكريرُ اللعنِ لتكريرِ القبح، فاجتنب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ جريمةِ ردِّ الحقِّ عمدًا، واجتنابُها."},"action":{"text":"تأمّل تكريرَ الدعاء: ثم قُتِل — أي ثم لُعِن وعُذِّب مرّةً بعد مرّةٍ، كُرِّر الدعاءُ عليه تأكيدًا وتغليظًا — كيف قدّر — أي كيف دبّر ذلك التدبيرَ الباطلَ في ردِّ الحقّ؛ فكُرِّر التعجّبُ والذمُّ لعظمِ جرمه «ثم قتل كيف قدر»؛ ففي هذا بيانُ تكريرِ الدعاءِ على هذا الكافرِ باللعنِ والهلاك، وتكريرِ التعجّبِ من سوءِ تقديره، تأكيدًا لعظمِ جريمتِه في ردِّ الحقِّ عمدًا بعد معرفته؛ فردُّ الحقِّ عمدًا عن تدبيرٍ جريمةٌ عظيمةٌ يُضاعَف عليها الوعيد؛ فاعلم أنت عظمَ جريمةِ من يردّ الحقَّ ويطعن فيه عن قصدٍ وتدبير، واجتنب ذلك غايةَ الاجتناب؛ ويلٌ لكلِّ أفّاكٍ أثيم * يسمع آياتِ الله تُتلى عليه ثم يصرّ مستكبرًا؛ فالتغليظُ في الوعيدِ بقدرِ عظمِ الجرم؛ فاستعظم جريمةَ ردِّ الحقِّ عمدًا، واجتنبها، وأذعِن للحقّ؛ فمن أذعن للحقِّ سلم، ومن ردّه عمدًا تكرّر عليه اللعن؛ فاجعل استعظامَ جريمةِ ردِّ الحقِّ عمدًا واجتنابَها دأبك."}},{"n":21,"reflection":{"text":"«ثم نظر» — ثم نظر وأعاد النظرَ في القرآنِ أو في وجوهِ الناسِ يلتمس ما يقول؛ ففي هذا بيانُ تردّدِه وتكلّفِه في ردِّ الحقّ؛ فاحذر أن يُوصِلك النظرُ المتكرّرُ إلى ردِّ الحقّ، بل ليُوصِلك إلى قبوله، فالنظرُ نعمةٌ تُساق للحقِّ أو للباطل، فوجّهه للحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توجيهُ النظرِ والتأمّلِ إلى الحقّ، والحذرُ من تسخيرِه للباطل."},"action":{"text":"تأمّل تردّدَه: ثم نظر — أي ثم أعاد النظرَ والتأمّلَ في القرآنِ وفيما يقول، أو نظر في وجوهِ أصحابه يلتمس رأيهم، متردّدًا متكلّفًا في التماسِ طعنٍ يطعن به «ثم نظر»؛ ففي هذا بيانُ تردّدِ هذا الكافرِ وتكلّفِه وإعادتِه النظرَ مرّةً بعد مرّةٍ في ردِّ الحقّ، مع أنه يعلم في قرارةِ نفسه أنه حقّ؛ فمن سخّر نظره وتأمّله لردِّ الحقّ حُرِم بركته؛ فاحذر أنت أن يُوصِلك النظرُ المتكرّرُ والتأمّلُ إلى ردِّ الحقِّ والطعنِ فيه، بل اجعل نظرك وتأمّلك سبيلًا إلى معرفةِ الحقِّ وقبوله؛ قل انظروا ماذا في السماواتِ والأرض؛ أولم ينظروا في ملكوتِ السماواتِ والأرض؛ أفلا ينظرون إلى الإبلِ كيف خُلِقت؛ فالنظرُ والتأمّلُ نعمةٌ تُوصِل إلى الحقِّ إن أُخلِصت، وإلى الباطلِ إن سُخِّرت له؛ فوجّه نظرك للحقّ، ولا تسخّره للطعنِ والردّ؛ فمن نظر ليهتدي اهتدى، ومن نظر ليطعن ضلّ؛ فاجعل توجيهَ النظرِ إلى الحقِّ دأبك."}},{"n":22,"reflection":{"text":"«ثم عبس وبسر» — ثم قطّب وجهه وكلّح وكرّه وجهه لمّا أعياه أن يجد في القرآنِ مطعنًا؛ ففي هذا بيانُ ضيقِ الكافرِ بالحقِّ حتى بدا في وجهه؛ فاحذر أن يضيق صدرك بالحقّ، بل انشرح له، فالعبوسُ من الحقِّ علامةُ الإعراض، فاستقبل الحقَّ بانشراح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استقبالُ الحقِّ بانشراحٍ لا بضيقٍ وعبوس."},"action":{"text":"تأمّل ضيقَه بالحقّ: ثم عبس — أي قطّب وجهه وجمعه وكلّح — وبسر — أي كره وجهه وكلح كلوحًا شديدًا وأظهر العبوسَ والكراهية؛ وذلك لمّا أعياه أن يجد في القرآنِ عيبًا يطعن به، فضاق به ذرعًا فظهر الضيقُ في وجهه «ثم عبس وبسر»؛ ففي هذا بيانُ شدّةِ ضيقِ هذا الكافرِ بالحقِّ حتى بدا العبوسُ والكراهيةُ في وجهه، لأنه لم يجد للقرآنِ مطعنًا وهو يريد ردّه؛ فالعبوسُ والضيقُ بالحقِّ علامةُ الإعراضِ والكبر؛ فاحذر أنت أن يضيق صدرك بالحقِّ أو يعبس وجهك عند سماعه، بل استقبله بانشراحِ صدرٍ وقبولٍ وفرح؛ وإذا تُتلى عليهم آياتنا بيّناتٍ تعرف في وجوهِ الذين كفروا المنكر؛ الذين آتيناهم الكتابَ يفرحون بما أُنزِل إليك؛ فمن ضاق بالحقِّ وعبس فقد أعرض، ومن انشرح له فقد قبِل؛ فاستقبل الحقَّ بانشراحٍ وقبول، ولا تضق به؛ فمن انشرح للحقِّ اهتدى، ومن عبس عنه ضلّ؛ فاجعل استقبالَ الحقِّ بانشراحٍ دأبك."}},{"n":23,"reflection":{"text":"«ثم أدبر واستكبر» — ثم أعرض عن الحقِّ وولّى، واستكبر عن اتّباعِ النبيِّ ﷺ وقبولِ القرآن؛ ففي هذا بيانُ أنّ الكبرَ والإعراضَ أصلُ ردِّ الحقّ؛ فاحذر الكبرَ والإعراضَ فإنهما يصدّان عن الحقّ، فالاستكبارُ عن الحقِّ مهلكة، فتواضع للحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ للحقِّ وقبولُه، والحذرُ من الكبرِ والإعراض."},"action":{"text":"تأمّل أصلَ ردِّه: ثم أدبر — أي أعرض عن الحقِّ وولّى عنه — واستكبر — أي تكبّر عن اتّباعِ النبيِّ ﷺ والإذعانِ للقرآنِ والانقيادِ للحقّ، أنِفَ أن يتّبع محمدًا «ثم أدبر واستكبر»؛ ففي هذا بيانُ أنّ الحاملَ لهذا الكافرِ على ردِّ الحقِّ بعد معرفته هو الإدبارُ والاستكبار: الإعراضُ عن الحقِّ والأنفةُ من اتّباعه؛ فالكبرُ أصلُ ردِّ الحقّ، كما كان أصلَ كفرِ إبليس؛ فاحذر أنت الكبرَ عن الحقِّ والإعراضَ عنه، فإنهما يصدّانك عن الهدى، وتواضع للحقِّ متى تبيّن لك وإن جاءك من صغيرٍ أو ممّن تخالفه؛ إنّ الذين يستكبرون عن عبادتي سيدخلون جهنّم داخرين؛ الكبرُ بطرُ الحقِّ وغمطُ الناس؛ سأصرف عن آياتي الذين يتكبّرون في الأرضِ بغيرِ الحقّ؛ فالاستكبارُ عن الحقِّ سببُ الحرمانِ والهلاك، والتواضعُ له سبيلُ الهداية؛ فتواضع للحقّ، واقبله، واحذر الكبرَ والإعراض؛ فمن تواضع للحقِّ اهتدى، ومن استكبر عنه هلك؛ فاجعل التواضعَ للحقِّ والحذرَ من الكبرِ دأبك."}},{"n":24,"reflection":{"text":"«فقال إن هذا إلا سحر يؤثر» — فقال عن القرآن: ما هذا إلا سحرٌ يُنقَل ويُروى عن السحرةِ الأقدمين؛ ففي هذا بيانُ افترائه على القرآنِ بأنه سحر؛ فنزّه القرآنَ عن أقوالِ المفترين، فرميُ الحقِّ بالسحرِ فِريةُ المعاندين، فأعظِم القرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ وتنزيهُه عن فِرى المعاندين."},"action":{"text":"تأمّل فريتَه على القرآن: فقال — بعد ذلك التفكيرِ والتقديرِ والعبوسِ والاستكبار — إن هذا — أي ما هذا القرآنُ — إلا سحرٌ يؤثر — أي إلا سحرٌ يُنقَل ويُروى ويُتعلَّم عن السحرةِ الأقدمين، أراد أن يصرف الناسَ عنه بوصفه بالسحر «فقال إن هذا إلا سحر يؤثر»؛ ففي هذا بيانُ افتراءِ هذا الكافرِ على القرآنِ العظيم بأنه سحرٌ مأثور، بعد أن أعياه أن يجد فيه مطعنًا حقيقيًّا، فرماه بأشنعِ الفِرى ليصدّ عنه؛ فرميُ الحقِّ بالسحرِ فِريةُ المعاندين في كلِّ زمان؛ فنزّه أنت القرآنَ عن أقوالِ المفترين، وأعظِمه في قلبك، واعلم أنه كلامُ الله لا سحرٌ ولا قولُ بشر؛ وقال الظالمون إن تتّبعون إلا رجلًا مسحورًا؛ كذلك ما أتى الذين من قبلهم من رسولٍ إلا قالوا ساحرٌ أو مجنون؛ إنّ هذا إلا سحرٌ يؤثر؛ فرميُ القرآنِ والحقِّ بالسحرِ دأبُ المعاندين المفترين؛ فعظّم القرآن، ونزّهه عن فِراهم، وأيقن أنه كلامُ الله؛ فمن عظّم القرآنَ آمن به، ومن رماه بالباطلِ خسر؛ فاجعل تعظيمَ القرآنِ وتنزيهَه عن فِرى المعاندين دأبك."}},{"n":25,"reflection":{"text":"«إن هذا إلا قول البشر» — ما هذا إلا كلامُ البشرِ لا كلامُ الله؛ ففي هذا بيانُ إنكارِه أن يكون القرآنُ من عند الله؛ فأيقن أنّ القرآنَ كلامُ الله لا كلامُ بشر، فنسبةُ القرآنِ إلى البشرِ كفرٌ وجحود، فأيقن بأنه كلامُ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ القرآنَ كلامُ الله لا كلامُ البشر."},"action":{"text":"تأمّل جحودَه: إن هذا — أي ما هذا القرآنُ — إلا قولُ البشرِ — أي إلا كلامُ إنسانٍ يقوله محمدٌ أو يتعلّمه من غيره، ليس من عند الله؛ فأنكر أن يكون القرآنُ وحيًا إلهيًّا «إن هذا إلا قول البشر»؛ ففي هذا بيانُ جحودِ هذا الكافرِ لكونِ القرآنِ كلامَ الله، ونسبتِه إلى البشر، وهو أصلُ كفرِ المكذّبين بالوحي؛ فنسبةُ القرآنِ إلى البشرِ جحودٌ للحقِّ الواضح، فإنّ القرآنَ معجزٌ عجز البشرُ عن معارضته؛ فأيقن أنت بأنّ القرآنَ كلامُ الله المنزَّلُ على نبيّه، لا كلامَ بشرٍ ولا سحرٍ ولا شعر، ففيه من الإعجازِ والهدى ما يشهد أنه من عند الله؛ قل لئن اجتمعتِ الإنسُ والجنُّ على أن يأتوا بمثلِ هذا القرآنِ لا يأتون بمثله؛ أم يقولون تقوّله بل لا يؤمنون فليأتوا بحديثٍ مثله؛ سأصليه سقر؛ فنسبةُ القرآنِ إلى البشرِ كفرٌ يُوجِب سقر، واليقينُ بأنه كلامُ الله إيمانٌ ونجاة؛ فأيقن بأنه كلامُ الله، وأعظِمه، واتّبعه؛ فمن أيقن بأنه كلامُ الله آمن، ومن نسبه إلى البشرِ كفر؛ فاجعل اليقينَ بأنّ القرآنَ كلامُ الله دأبك."}},{"n":26,"reflection":{"text":"«سأصليه سقر» — سأُدخِله وأُحرِقه في سقر (اسمٍ من أسماءِ جهنّم)؛ ففي هذا بيانُ جزاءِ من كذّب القرآنَ ونسبه للبشر؛ فاحذر أن تُصلى سقرَ بتكذيبِ الحقّ، فجزاءُ تكذيبِ القرآنِ الإصلاءُ في سقر، فآمن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من جزاءِ تكذيبِ القرآن: الإصلاءِ في سقر."},"action":{"text":"تأمّل جزاءَ المكذّب: سأُصليه — أي سأُدخِله وأُلقيه فأُحرِقه — سقرَ — وهي اسمٌ من أسماءِ جهنّمَ، أو دركةٌ من دركاتها؛ فهذا جزاءُ تكذيبه القرآنَ ونسبتِه إيّاه إلى البشرِ والسحر «سأصليه سقر»؛ ففي هذا بيانُ جزاءِ من كذّب القرآنَ وردّ الحقَّ عنادًا: أنه يُصلى سقرَ ويُحرَق فيها؛ فجزاءُ تكذيبِ القرآنِ ونسبتِه إلى غيرِ الله الإصلاءُ في سقر؛ فاحذر أنت أن تسلك سبيلَ المكذّبين فتُصلى سقر، وآمن بالقرآنِ وعظّمه واتّبعه لتنجو؛ وأمّا من خفّت موازينه فأمّه هاوية * وما أدراك ما هيه * نارٌ حامية؛ يصلونها فبئس المصير؛ لا تبقي ولا تذر؛ فالإصلاءُ في سقر جزاءُ من كذّب القرآنَ ورماه بالباطل؛ فآمن به، وأعظِمه، واحذر سبيلَ المكذّبين؛ فمن آمن بالقرآنِ نجا، ومن كذّبه صُلِي سقر؛ فاجعل الحذرَ من جزاءِ تكذيبِ القرآنِ دأبك."}},{"n":27,"reflection":{"text":"«وما أدراك ما سقر» — وأيُّ شيءٍ أعلمك ما سقر؟ استفهامُ تهويلٍ لأمرها وتعظيمٍ لشأنها؛ ففي هذا بيانُ عظمِ هولِ سقرَ حتى لا تُدرَك كنهُها؛ فاستحضر هولَ سقرَ التي لا يُحيط بها الوصف، فسقرُ أعظمُ من أن يُدرِكها العقل، فاتّقها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ سقرَ الذي يفوق الوصفَ واتّقاؤها."},"action":{"text":"تأمّل تهويلَ سقر: وما أدراك ما سقرُ — أي أيُّ شيءٍ أعلمك وأخبرك بحقيقةِ سقرَ وكنهِ هولها؟ وهو استفهامٌ للتهويلِ والتعظيمِ لأمرها، إشعارًا بأنّ هولها يفوق الإدراكَ والوصف «وما أدراك ما سقر»؛ ففي هذا بيانُ عظمِ شأنِ سقرَ وهولها، وأنها من الفظاعةِ بحيث لا يُحيط بكنهها علمُ أحدٍ إلا الله؛ فسقرُ أعظمُ وأهولُ من أن يُدرِكها العقلُ أو يُحيط بها الوصف؛ فاستحضر أنت هولَ سقرَ وعظمَ عذابها، واتّقِها بالإيمانِ والعملِ الصالحِ والبعدِ عن أسبابِ دخولها؛ وما أدراك ما الحطمة * نارُ الله الموقدة؛ وما أدراك ما هيه * نارٌ حامية؛ فاتّقوا النارَ التي وقودها الناسُ والحجارة؛ فسقرُ هولٌ يفوق الوصفَ والإدراك، واتّقاؤها بالإيمانِ والعمل؛ فاستحضر هولها، واتّقها، واعمل لِما ينجّيك منها؛ فمن اتّقاها بالعملِ نجا، ومن تهاون بها ورد؛ فاجعل استحضارَ هولِ سقرَ واتّقاءَها دأبك."}},{"n":28,"reflection":{"text":"«لا تبقي ولا تذر» — لا تُبقِي فيهم شيئًا إلا أحرقته، ولا تذرهم حتى يموتوا فيستريحوا، بل تعيدهم فتحرقهم أبدًا؛ ففي هذا بيانُ دوامِ عذابِ سقرَ وشدّته؛ فاحذر نارًا لا تُبقي ولا تذر، فعذابُ سقرَ دائمٌ لا انقطاعَ له، فاتّقِ ما يُوردها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من دوامِ عذابِ سقرَ الذي لا انقطاعَ له."},"action":{"text":"تأمّل دوامَ عذابها: لا تُبقي — أي لا تُبقي على من فيها شيئًا إلا أحرقته وأتت عليه، تأكل لحومهم وعظامهم وجلودهم — ولا تذر — أي لا تتركهم على حالٍ، ولا تذرهم يموتون فيستريحون، بل كلّما نضجت جلودهم بُدِّلوا غيرها ليذوقوا العذابَ أبدًا «لا تبقي ولا تذر»؛ ففي هذا بيانُ دوامِ عذابِ سقرَ وشدّته، وأنها لا تُبقي على أهلها ولا تدعهم يستريحون بموتٍ أو انقطاع؛ فعذابُ سقرَ دائمٌ متجدّدٌ لا انقطاعَ له ولا راحةَ فيه؛ فاحذر أنت نارًا لا تُبقي ولا تذر، واتّقِ ما يُوردها من الكفرِ والمعاصي والإصرار؛ كلّما نضجت جلودهم بدّلناهم جلودًا غيرها ليذوقوا العذاب؛ لا يُقضى عليهم فيموتوا ولا يُخفَّف عنهم من عذابها؛ لا تبقي ولا تذر؛ فعذابُ سقرَ دائمٌ لا موتَ فيه ولا راحة؛ فاتّقِ أسبابها، وآمن، واعمل صالحًا؛ فمن اتّقاها نجا من دوامِ عذابها، ومن ورَدها لم تُبقِ عليه؛ فاجعل الحذرَ من دوامِ عذابِ سقرَ دأبك."}},{"n":29,"reflection":{"text":"«لواحة للبشر» — مُغيِّرةٌ للجلودِ محرِقةٌ لها تُسوّدها وتُلوّحها (أو ظاهرةٌ للبشر يرونها)؛ ففي هذا بيانُ شدّةِ أثرِ سقرَ في أجسادِ أهلها؛ فاحذر نارًا تُلوّح الجلودَ وتُغيّرها، فأثرُ سقرَ في الأبدانِ فظيع، فاتّقِ ما يُوردها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من شدّةِ سقرَ وأثرِها في الأبدان."},"action":{"text":"تأمّل أثرَها في الأبدان: لوّاحةٌ للبشر — أي مُغيِّرةٌ للجلودِ محرِقةٌ لها، تُلوّح جلودَ أهلها فتُسوّدها وتُحرِقها حتى تدعها أشدَّ سوادًا من الليل؛ وقيل: البشرُ جمعُ بشرة، أي مُحرِقةٌ للبشرةِ ظاهرةٌ لها؛ وقيل: تلوح وتظهر للناسِ من بعيد «لواحة للبشر»؛ ففي هذا بيانُ شدّةِ أثرِ سقرَ في أجسادِ أهلها، وأنها تُلوّح جلودهم وتُغيّرها وتُحرِقها؛ فأثرُ سقرَ في الأبدانِ فظيعٌ مُهلِك؛ فاحذر أنت نارًا تُلوّح الجلودَ وتُسوّدها وتأتي على الأبدان، واتّقِ ما يُوردها؛ تكاد تميّز من الغيظ؛ وجوهٌ يومئذٍ عليها غبرة * ترهقها قترة؛ سرابيلهم من قطرانٍ وتغشى وجوههم النار؛ فسقرُ تُلوّح الأبدانَ وتُحرِقها أشنعَ إحراق؛ فاتّقِ أسبابها، وآمن، واعمل صالحًا؛ فمن اتّقاها سلم بدنه، ومن ورَدها لوّحته وأحرقته؛ فاجعل الحذرَ من شدّةِ سقرَ وأثرِها في الأبدانِ دأبك."}},{"n":30,"reflection":{"text":"«عليها تسعة عشر» — على سقرَ من الملائكةِ الموكَّلين بها تسعةَ عشرَ (خزنةً غلاظًا شدادًا)؛ ففي هذا بيانُ عددِ خزنةِ النارِ الغلاظِ الشداد؛ فاتّقِ نارًا يتولّاها ملائكةٌ غلاظٌ شداد، فخزنةُ سقرَ لا يعصون الله، فاتّقِ ما يُوردها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ خزنةِ النارِ الغلاظِ الشداد واتّقاءُ ما يُوردها."},"action":{"text":"تأمّل خزنةَ النار: عليها — أي على سقرَ موكَّلون بها من الملائكة — تسعةَ عشرَ — أي تسعةَ عشرَ مَلَكًا هم خزنتها ورؤساؤها، غلاظٌ شدادٌ لا يعصون الله ما أمرهم؛ فهم على كثرةِ أهلها كافون بأمرِ الله «عليها تسعة عشر»؛ ففي هذا بيانُ عددِ خزنةِ سقرَ من الملائكةِ الغلاظِ الشداد، الموكَّلين بعذابِ أهلها؛ فخزنةُ النارِ ملائكةٌ أقوياءُ غلاظٌ لا يرحمون ولا يعصون الله؛ فاتّقِ أنت نارًا يتولّى عذابَ أهلها ملائكةٌ غلاظٌ شداد، واعمل لِما ينجّيك من سطوتهم؛ عليها ملائكةٌ غلاظٌ شدادٌ لا يعصون الله ما أمرهم ويفعلون ما يؤمرون؛ وما جعلنا أصحابَ النارِ إلا ملائكة؛ فخزنةُ سقرَ الغلاظُ الشدادُ دليلٌ على شدّةِ عذابها؛ فاستحضر ذلك، واتّقِ ما يُوردها، وآمن واعمل؛ فمن اتّقى نجا من سطوتهم، ومن كذّب سُلِّطوا عليه؛ فاجعل استحضارَ خزنةِ النارِ واتّقاءَ ما يُوردها دأبك."}}]},{"title":"حكمةُ عددِ خزنةِ النارِ فتنةً وذكرى","range":[31,31],"theme":"بيانُ أنّ خزنةَ النارِ ملائكة، وأنّ عددهم فتنةٌ تُميّز المؤمنَ من المرتاب «ليستيقن الذين أوتوا الكتاب ويزداد الذين آمنوا إيمانا... وما يعلم جنود ربك إلا هو وما هي إلا ذكرى للبشر»","verses":[{"n":31,"reflection":{"text":"«وما جعلنا أصحاب النار إلا ملائكة وما جعلنا عدتهم إلا فتنة للذين كفروا... وما هي إلا ذكرى للبشر» — وما جعلنا خزنةَ النارِ إلا ملائكةً (لا يُطاقون)، وما جعلنا عددهم (١٩) إلا فتنةً واختبارًا: ليكفر به المكذّبون ويستيقن أهلُ الكتابِ ويزداد المؤمنون إيمانًا، وما يعلم جنودَ ربّك إلا هو، وما سقرُ (أو الآياتُ) إلا تذكرةٌ للبشر؛ ففي هذا بيانُ حكمةِ الله في العدد، وأنّ الغيبَ يُميّز المؤمنَ من المرتاب؛ فسلّم لله في غيبه وازدد إيمانًا بما أخبر، فالتسليمُ للغيبِ يزيد الإيمان، فسلّم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لأخبارِ الله الغيبيّة وازديادُ الإيمانِ بها، والحذرُ من الارتياب."},"action":{"text":"تأمّل حكمةَ العدد: وما جعلنا أصحابَ النارِ — أي خزنتها القائمين على عذابِ أهلها — إلا ملائكةً — لا بشرًا ولا ما يُطيقه أهلُ النارِ مغالبته — وما جعلنا عدّتهم — أي عددهم تسعةَ عشرَ — إلا فتنةً للذين كفروا — أي اختبارًا وابتلاءً لهم (استقلّه أبو جهلٍ فقال: أيعجز كلُّ عشرةٍ منكم عن واحد؟) — ليستيقن الذين أوتوا الكتابَ — أي يزداد أهلُ الكتابِ يقينًا بصدقِ النبيِّ لموافقته كتبهم — ويزداد الذين آمنوا إيمانًا — بتصديقهم — ولا يرتاب الذين أوتوا الكتابَ والمؤمنون — أي لا يشكّون — وليقول الذين في قلوبهم مرضٌ والكافرون: ماذا أراد الله بهذا مثلًا — استنكارًا — كذلك يُضلّ الله من يشاء ويهدي من يشاء — بعدله وفضله — وما يعلم جنودَ ربّك إلا هو — أي جنودُه أكثرُ من أن يُحصيها غيره — وما هي إلا ذكرى للبشر — أي وما سقرُ (أو هذه الآياتُ والموعظة) إلا تذكرةٌ للبشرِ ليتذكّروا ويتّعظوا «وما جعلنا أصحاب النار إلا ملائكة...»؛ ففي هذا بيانُ حكمةِ الله في جعلِ عددِ الخزنةِ فتنةً تُميّز المؤمنَ المسلّمَ من المرتابِ المعاند، وأنّ التسليمَ لأخبارِ الله الغيبيّةِ يزيد الإيمان، وأنّ الارتيابَ فيها من مرضِ القلب، وأنّ جنودَ الله لا يعلمها إلا هو؛ فالتسليمُ للغيبِ سبيلُ زيادةِ الإيمان، والارتيابُ فيه سبيلُ الضلال؛ فسلّم أنت لكلِّ ما أخبر الله به من الغيبِ وإن لم تُدرِك حكمته، وازدد إيمانًا بتصديقه، ولا ترتب فيه ولا تعترض؛ الذين يؤمنون بالغيب؛ وما أوتيتم من العلمِ إلا قليلًا؛ آمنّا به كلٌّ من عند ربّنا؛ فالتسليمُ لأخبارِ الله يزيد الإيمان، والاعتراضُ عليها مرضٌ وضلال؛ فسلّم، وازدد إيمانًا، واحذر الارتياب؛ فمن سلّم للغيبِ ازداد إيمانًا، ومن ارتاب وضاع؛ فاجعل التسليمَ لأخبارِ الله وازديادَ الإيمانِ بها والحذرَ من الارتيابِ دأبك."}}]},{"title":"القسمُ على أنّ النارَ إحدى الكبرِ نذيرًا للبشر","range":[32,37],"theme":"القسمُ بالقمرِ والليلِ والصبح «كلا والقمر والليل إذ أدبر والصبح إذا أسفر»، وجوابُه «إنها لإحدى الكبر نذيرا للبشر»، وأنّ الأمرَ بمشيئةِ العبد «لمن شاء منكم أن يتقدم أو يتأخر»","verses":[{"n":32,"reflection":{"text":"«كلا والقمر» — حقًّا، أُقسِم بالقمر؛ ففي هذا ردعٌ للمكذّبين وقسمٌ بآيةٍ من آياتِ الله على عظمِ شأنِ سقرَ أو القرآن؛ فعظّم آياتِ الله التي أقسم بها، فالقسمُ بالمخلوقاتِ العظيمةِ يدلّ على عظمِ المُقسَمِ عليه، فتأمّل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله واستشعارُ عظمِ ما أقسم عليه."},"action":{"text":"تأمّل القسمَ بالقمر: كلّا — أي حقًّا، وردعًا للمكذّبين عمّا هم عليه من إنكارِ سقرَ والاستهزاءِ بعددِ خزنتها — والقمرِ — أي أُقسِم بالقمرِ الذي هو آيةٌ من آياتِ الله الباهرة «كلا والقمر»؛ ففي هذا بيانُ ردعِ المكذّبين، ثم القسمِ بالقمرِ (آيةِ الله العظيمة) تعظيمًا لشأنِ ما أُقسِم عليه من أمرِ سقرَ أو القرآنِ أو القيامة؛ فالقسمُ بالمخلوقاتِ العظيمةِ يدلّ على عظمِ المُقسَمِ عليه وعظمِ المُقسِمِ به؛ فعظّم أنت آياتِ الله في خلقه (كالقمرِ والليلِ والصبح)، واستشعر عظمَ ما أقسم الله عليه من أمرِ الآخرة؛ والشمسِ وضحاها والقمرِ إذا تلاها؛ فتبارك الذي جعل في السماءِ بروجًا وجعل فيها سراجًا وقمرًا منيرًا؛ فآياتُ الله في الكونِ دلائلُ على عظمته، وقسمُه بها تعظيمٌ لِما أقسم عليه؛ فعظّمها، وتأمّلها، واستشعر عظمَ الآخرة؛ فمن عظّم آياتِ الله اتّعظ، ومن غفل عنها خسر؛ فاجعل تعظيمَ آياتِ الله واستشعارَ عظمِ ما أقسم عليه دأبك."}},{"n":33,"reflection":{"text":"«والليل إذ أدبر» — وأُقسِم بالليلِ إذ ولّى وأدبر ذاهبًا؛ ففي هذا قسمٌ بآيةِ الليلِ المدبرِ الدالّةِ على قدرةِ الله وتدبيره؛ فتأمّل تعاقبَ الليلِ والنهارِ آيةً على قدرةِ الله، فإدبارُ الليلِ آيةٌ من آياتِ الله، فتأمّلها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ آيةِ تعاقبِ الليلِ والنهارِ ودلالتِها على القدرة."},"action":{"text":"تأمّل القسمَ بالليلِ المدبر: والليلِ إذ أدبر — أي أُقسِم بالليلِ حين يولّي ويدبر ويذهب ظلامه مؤذنًا بمجيءِ النهار؛ وهو آيةٌ من آياتِ الله في تعاقبِ الليلِ والنهارِ بنظامٍ محكم «والليل إذ أدبر»؛ ففي هذا بيانُ القسمِ بالليلِ المدبرِ الدالِّ على قدرةِ الله وحكمتِه في تدبيرِ الكون، تعظيمًا لِما أُقسِم عليه؛ فتعاقبُ الليلِ والنهارِ آيةٌ من آياتِ الله الباهرة؛ فتأمّل أنت آيةَ إدبارِ الليلِ وإقبالِ النهار، واستدلّ بها على قدرةِ الله وتدبيره وعظمته؛ وجعلنا الليلَ لباسًا وجعلنا النهارَ معاشًا؛ وآيةٌ لهم الليلُ نسلخ منه النهار؛ يُغشي الليلَ النهارَ يطلبه حثيثًا؛ فتعاقبُ الليلِ والنهارِ آيةٌ على قدرةِ الله وحكمته وعظمِ ما أقسم عليه؛ فتأمّلها، واستدلّ بها، واعتبر؛ فمن تأمّل آياتِ الله اهتدى، ومن غفل عنها حُرِم؛ فاجعل تأمّلَ آيةِ تعاقبِ الليلِ والنهارِ دأبك."}},{"n":34,"reflection":{"text":"«والصبح إذا أسفر» — وأُقسِم بالصبحِ إذا أضاء وانكشف ظلامُه؛ ففي هذا قسمٌ بآيةِ الصبحِ المسفرِ الدالّةِ على قدرةِ الله؛ فتأمّل انبلاجَ الصبحِ آيةً على قدرةِ الله ورحمته، فإسفارُ الصبحِ آيةٌ ونعمة، فتأمّلها واشكرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ آيةِ الصبحِ المسفرِ وشكرُ نعمةِ النور."},"action":{"text":"تأمّل القسمَ بالصبح: والصبحِ إذا أسفر — أي أُقسِم بالصبحِ حين يُسفِر ويُضيء وينكشف ظلامُه ويظهر نوره؛ وهو آيةٌ من آياتِ الله ونعمةٌ عظيمةٌ على العباد «والصبح إذا أسفر»؛ ففي هذا بيانُ القسمِ بالصبحِ المسفرِ الدالِّ على قدرةِ الله ورحمته، تعظيمًا لِما أُقسِم عليه؛ فانبلاجُ الصبحِ بعد ظلمةِ الليلِ آيةٌ ونعمةٌ من الله؛ فتأمّل أنت آيةَ الصبحِ إذا أسفر، واستدلّ بها على قدرةِ الله ورحمته، واشكر نعمةَ النورِ والحياةِ بعد ظلمةِ الليل؛ فالقِ الإصباحِ وجعل الليلَ سكنًا؛ قل أرأيتم إن جعل الله عليكم الليلَ سرمدًا إلى يومِ القيامةِ من إلهٌ غيرُ الله يأتيكم بضياء؛ فإسفارُ الصبحِ آيةٌ على القدرةِ ونعمةٌ تستوجب الشكر؛ فتأمّلها، واشكرها، واستدلّ بها؛ فمن تأمّل آياتِ الله وشكر اهتدى، ومن غفل كفر النعمة؛ فاجعل تأمّلَ آيةِ الصبحِ وشكرَ نعمةِ النورِ دأبك."}},{"n":35,"reflection":{"text":"«إنها لإحدى الكبر» — إنّ سقرَ لإحدى الدواهي الكبرِ العظام (أعظمِ ما يُنذَر به)؛ ففي هذا بيانُ عظمِ شأنِ سقرَ وأنها من كبارِ الأمور؛ فاستعظم أمرَ النارِ فإنها إحدى الكبر، فسقرُ داهيةٌ كبرى، فاتّقها واعمل لِما ينجّي منها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ أمرِ النارِ والعملُ لِما ينجّي منها."},"action":{"text":"تأمّل عظمَ شأنِ سقر: إنها — أي سقرَ — لإحدى الكبرِ — أي لإحدى الدواهي الكبرِ العظام، ومن أكبرِ ما يُنذَر به من العذاب، ومن أعظمِ آياتِ الله المخوّفة؛ فهي داهيةٌ عظيمةٌ لا يُستهان بها «إنها لإحدى الكبر»؛ ففي هذا بيانُ عظمِ شأنِ سقرَ وأنها من كبارِ الأمورِ وأفظعِ ما يُنذَر به الناس، جوابُ القسمِ المتقدّم؛ فسقرُ داهيةٌ كبرى تستحقّ أعظمَ الحذر؛ فاستعظم أنت أمرَ النارِ ولا تستهن بها، واعمل جادًّا لِما ينجّيك منها من الإيمانِ والتقوى والعملِ الصالح؛ يومَ يرون الملائكةَ لا بشرى يومئذٍ للمجرمين؛ فاتّقوا النارَ التي وقودها الناسُ والحجارة؛ إنّ عذابها كان غرامًا؛ فسقرُ من أعظمِ الأهوال، والعاقلُ من استعظمها فعمل لِما ينجّيه منها؛ فاستعظمها، واعمل، ولا تستهن بأمرها؛ فمن استعظم النارَ وعمل لنجاته نجا، ومن استهان بها ورَدها؛ فاجعل استعظامَ أمرِ النارِ والعملَ لِما ينجّي منها دأبك."}},{"n":36,"reflection":{"text":"«نذيرا للبشر» — نذيرًا للبشرِ يُنذَرون به (سقرُ، أو النبيُّ، أو القرآن)؛ ففي هذا بيانُ أنّ الإنذارَ بسقرَ رحمةٌ لتنبيهِ الناسِ قبل الفوات؛ فاتّعظ بالنذيرِ قبل حلولِ العذاب، فالإنذارُ رحمةٌ فاغتنمها، فاتّعظ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالنذيرِ واغتنامُ الإنذارِ قبل الفوات."},"action":{"text":"تأمّل رحمةَ الإنذار: نذيرًا للبشر — أي إنّ سقرَ (أو هذا القرآنَ، أو النبيَّ محمدًا ﷺ) نذيرٌ للبشرِ يُنذَرون به عذابَ الله، ليحذروا ويتّقوا قبل نزوله «نذيرا للبشر»؛ ففي هذا بيانُ أنّ الإنذارَ بسقرَ وأهوالها رحمةٌ من الله بالبشر، إذ نبّههم على العذابِ قبل وقوعه ليتّقوه؛ فالإنذارُ رحمةٌ ونعمةٌ تستوجب الاتّعاظ؛ فاتّعظ أنت بالنذير، وخذ الإنذارَ على محملِ الجدِّ، واعمل لِما ينجّيك قبل أن يفوت الأوان؛ إنّا أرسلناك بالحقِّ بشيرًا ونذيرًا؛ وأنذر به الذين يخافون أن يُحشَروا إلى ربّهم؛ إنّ هذه تذكرةٌ فمن شاء اتّخذ إلى ربّه سبيلًا؛ فالإنذارُ رحمةٌ سابقةٌ للعذاب، والموفّقُ من اتّعظ به؛ فاتّعظ، واغتنم الإنذار، وبادر بالعمل؛ فمن اتّعظ بالنذيرِ نجا، ومن أعرض عنه هلك؛ فاجعل الاتّعاظَ بالنذيرِ واغتنامَ الإنذارِ دأبك."}},{"n":37,"reflection":{"text":"«لمن شاء منكم أن يتقدم أو يتأخر» — نذيرًا لمن شاء منكم أن يتقدّم إلى الخيرِ والطاعةِ أو يتأخّر عنها إلى الشرِّ والمعصية؛ ففي هذا بيانُ أنّ الأمرَ متعلّقٌ بمشيئةِ العبدِ واختيارِه في التقدّمِ أو التأخّر؛ فتقدّم إلى الخيرِ ولا تتأخّر، فالبابُ مفتوحٌ لمن شاء أن يتقدّم، فتقدّم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتقدّمِ إلى الخيرِ والطاعة، والحذرُ من التأخّر."},"action":{"text":"تأمّل بابَ الاختيار: لمن شاء منكم — أيها البشرُ — أن يتقدّم — أي إلى الإيمانِ والطاعةِ والخيرِ فيسعد — أو يتأخّر — أي عن ذلك إلى الكفرِ والمعصيةِ فيشقى؛ فالإنذارُ حجّةٌ على الجميع، والاختيارُ للعبد «لمن شاء منكم أن يتقدم أو يتأخر»؛ ففي هذا بيانُ أنّ الله فتح البابَ للناس، فمن شاء تقدّم إلى الخيرِ والطاعةِ فنجا، ومن شاء تأخّر إلى الشرِّ والمعصيةِ فهلك، وأنّ مشيئةَ العبدِ مندرجةٌ تحت مشيئةِ الله؛ فالتقدّمُ إلى الخيرِ نجاة، والتأخّرُ عنه هلاك؛ فتقدّم أنت إلى الخيرِ والطاعةِ والإيمان، وسابق إليها، ولا تتأخّر عنها ولا تسوّف؛ فاستبقوا الخيرات؛ وسارعوا إلى مغفرةٍ من ربّكم؛ سابقوا إلى مغفرةٍ من ربّكم وجنّة؛ فبابُ التقدّمِ إلى الخيرِ مفتوح، والموفّقُ من بادر ولم يتأخّر؛ فتقدّم، وسابق، ولا تسوّف؛ فمن تقدّم إلى الخيرِ سعد، ومن تأخّر عنه شقي؛ فاجعل المبادرةَ بالتقدّمِ إلى الخيرِ والحذرَ من التأخّرِ دأبك."}}]},{"title":"كلُّ نفسٍ رهينةٌ وحوارُ أهلِ الجنّةِ مع المجرمين","range":[38,48],"theme":"أنّ كلَّ نفسٍ «بما كسبت رهينة إلا أصحاب اليمين»، ومساءلتُهم للمجرمين «ما سلككم في سقر»، واعترافُ المجرمين بأسبابِ هلاكهم «لم نك من المصلين ولم نك نطعم المسكين وكنا نخوض مع الخائضين وكنا نكذب بيوم الدين حتى أتانا اليقين»، وحرمانِهم الشفاعة «فما تنفعهم شفاعة الشافعين»","verses":[{"n":38,"reflection":{"text":"«كل نفس بما كسبت رهينة» — كلُّ نفسٍ مرهونةٌ محبوسةٌ بعملها، مأخوذةٌ بكسبها عند الله؛ ففي هذا بيانُ أنّ كلَّ نفسٍ مرتهنةٌ بعملها تُجزى به؛ فاعمل صالحًا يفكّ رهانك، فنفسك رهينةٌ بعملها فافدها بالصالحات، فاعمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ النفسَ رهينةٌ بعملها، والعملُ لفكاكها."},"action":{"text":"تأمّل رهانَ النفس: كلُّ نفسٍ بما كسبت رهينةٌ — أي كلُّ نفسٍ محبوسةٌ مرهونةٌ عند الله بعملها الذي كسبته، مأخوذةٌ به، لا تُفكّ إلا بأداءِ ما عليها من حقوقِ الله؛ فهي كالرهنِ المحبوسِ حتى يُوفّى ما عليه «كل نفس بما كسبت رهينة»؛ ففي هذا بيانُ أنّ كلَّ نفسٍ مرتهنةٌ بكسبها، مأخوذةٌ بعملها، تُجزى بما قدّمت من خيرٍ أو شرّ، لا يحمل عنها أحدٌ شيئًا؛ فالنفسُ رهينةٌ بعملها، ففكاكها بالعملِ الصالح؛ فاعمل أنت صالحًا يفكّ رهانَ نفسك ويُخلِّصها من الحبس، وأدِّ حقوقَ الله وحقوقَ العباد؛ ولا تزر وازرةٌ وزرَ أخرى؛ كلُّ امرئٍ بما كسب رهين؛ من عمل صالحًا فلنفسه ومن أساء فعليها؛ فنفسك مرهونةٌ بعملها، وفكاكها بالإيمانِ والطاعةِ وأداءِ الحقوق؛ فاعمل لفكاكها، وأدِّ ما عليك، ولا تُثقِلها بالأوزار؛ فمن فكّ نفسه بالعملِ الصالحِ نجا، ومن أوبقها بالأوزارِ حُبِست؛ فاجعل استحضارَ أنّ النفسَ رهينةٌ والعملَ لفكاكها دأبك."}},{"n":39,"reflection":{"text":"«إلا أصحاب اليمين» — إلا أصحابَ اليمين (أهلَ السعادةِ والإيمانِ الذين أخذوا كتبهم بأيمانهم) فإنهم فكّوا رهانهم بالإيمانِ والعملِ الصالح؛ ففي هذا بيانُ نجاةِ أصحابِ اليمينِ من الرهان؛ فاعمل لتكون من أصحابِ اليمينِ الذين فُكَّ رهانهم، فأصحابُ اليمينِ ناجون فاطلب صحبتهم، فاعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ أن تكون من أصحابِ اليمينِ بالإيمانِ والعمل."},"action":{"text":"تأمّل استثناءَ أصحابِ اليمين: إلا أصحابَ اليمين — أي إلا أهلَ السعادةِ والإيمانِ الذين يُؤتَون كتبهم بأيمانهم، فإنهم غيرُ مرهونين بأعمالهم، بل فكّوا رهانهم بإيمانهم وعملهم الصالح وتوبتهم، فنجت أنفسهم وسلمت من الحبس «إلا أصحاب اليمين»؛ ففي هذا بيانُ أنّ أصحابَ اليمينِ (أهلَ الإيمانِ والطاعة) استثناهم الله من رهانِ الأنفس، لأنهم أدّوا ما عليهم ففُكَّ رهانهم؛ فأصحابُ اليمينِ ناجون سعداء؛ فاعمل أنت لتكون منهم بالإيمانِ والعملِ الصالحِ والتوبةِ وأداءِ الحقوق، واطلب صحبتهم ومنازلهم؛ وأصحابُ اليمينِ ما أصحابُ اليمين * في سدرٍ مخضود؛ فأمّا من أوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه؛ فأصحابُ اليمينِ فُكَّ رهانهم فنجوا وسعدوا؛ فاعمل لتكون منهم، وأدِّ الحقوق، وتب؛ فمن كان من أصحابِ اليمينِ نجا وسعد، ومن كان من غيرهم حُبِس بعمله؛ فاجعل طلبَ أن تكون من أصحابِ اليمينِ بالإيمانِ والعملِ دأبك."}},{"n":40,"reflection":{"text":"«في جنات يتساءلون» — هم في جناتٍ عظيمةٍ يسأل بعضهم بعضًا (أو يتساءلون عن حالِ المجرمين)؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ في الجنّةِ وتفكّههم بالحديث؛ فاعمل لتنال نعيمَ الجنّةِ ومجالسها، فالجنّةُ دارُ نعيمٍ وتساؤلٍ لأهلها، فاطلبها بعملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ نعيمِ الجنّةِ ومجالسِها بالعملِ الصالح."},"action":{"text":"تأمّل نعيمَ أصحابِ اليمين: في جناتٍ — أي هم في بساتينَ عظيمةٍ من نعيمِ الجنّةِ الدائم — يتساءلون — أي يسأل بعضهم بعضًا متفكّهين متحدّثين، ثم يتساءلون عن حالِ المجرمين في النار كما سيأتي «في جنات يتساءلون»؛ ففي هذا بيانُ ما أعدّ الله لأصحابِ اليمينِ من النعيمِ في الجنّات، وأنهم فيها يتحدّثون ويتساءلون في أمنٍ وسرورٍ ونعيم؛ فالجنّةُ دارُ النعيمِ والأمنِ والأنسِ لأهلها؛ فاعمل أنت لتنال نعيمَ الجنّةِ ومجالسَها وأنسَ أهلها، بالإيمانِ والعملِ الصالح؛ ونزعنا ما في صدورهم من غلٍّ إخوانًا على سررٍ متقابلين؛ فأقبل بعضهم على بعضٍ يتساءلون؛ فأصحابُ اليمينِ في نعيمٍ وأنسٍ وتساؤلٍ في الجنّات؛ فاعمل لتنالها، وقدّم لنفسك، واطلب صحبةَ أهلها؛ فمن عمل لها نالها، ومن أعرض حُرِمها؛ فاجعل طلبَ نعيمِ الجنّةِ بالعملِ الصالحِ دأبك."}},{"n":41,"reflection":{"text":"«عن المجرمين» — يتساءلون عن المجرمين: ما الذي أوردهم النار؟ ففي هذا بيانُ سؤالِ أهلِ الجنّةِ عن سببِ هلاكِ المجرمين للاعتبار؛ فتأمّل أسبابَ هلاكِ المجرمين لتجتنبها، فمعرفةُ أسبابِ الهلاكِ سبيلُ اجتنابها، فتأمّلها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تأمّلُ أسبابِ هلاكِ المجرمين لاجتنابها."},"action":{"text":"تأمّل سؤالَهم عن المجرمين: عن المجرمين — أي يتساءل أصحابُ الجنّةِ عن حالِ المجرمين وما الذي أوقعهم في العذاب، أو يسألون المجرمين أنفسهم عن سببِ دخولهم النار؛ فيكون سؤالُ توبيخٍ للمجرمين واعتبارٍ لأهلِ الجنّة «عن المجرمين»؛ ففي هذا بيانُ أنّ أهلَ الجنّةِ يتساءلون ويسألون عن المجرمين وسببِ هلاكهم، ليظهر فضلُ الله عليهم وليكون في ذلك عبرةٌ وبيانٌ لأسبابِ الهلاك؛ فمعرفةُ أسبابِ الهلاكِ سبيلٌ إلى اجتنابها؛ فتأمّل أنت أسبابَ هلاكِ المجرمين التي ستُذكَر (تركِ الصلاةِ وإطعامِ المسكينِ والخوضِ والتكذيب) لتجتنبها وتحذرها؛ وأقبل بعضهم على بعضٍ يتساءلون * قالوا إنّا كنّا قبل في أهلنا مشفقين؛ فأقبل بعضهم على بعضٍ يتساءلون * قال قائلٌ منهم إني كان لي قرين؛ فتأمّلُ أسبابِ هلاكِ المجرمين طريقٌ لاجتنابها؛ فتأمّلها، واحذرها، واجتنبها؛ فمن اجتنب أسبابَ الهلاكِ نجا، ومن قارفها هلك؛ فاجعل تأمّلَ أسبابِ هلاكِ المجرمين لاجتنابها دأبك."}},{"n":42,"reflection":{"text":"«ما سلككم في سقر» — يسألونهم: ما الذي أدخلكم وأوردكم سقر؟ ففي هذا بيانُ السؤالِ عن سببِ دخولِ النارِ تقريعًا واعتبارًا؛ فاسأل نفسك: ما الذي يُوردني سقر فأجتنبه؟ فالسؤالُ عن سببِ العذابِ يُثمِر اجتنابه، فتفقّد نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفسِ عمّا يُورِد النارَ لاجتنابه."},"action":{"text":"تأمّل السؤالَ الموجّه للمجرمين: ما سلككم — أي ما الذي أدخلكم وأوردكم وأولجكم — في سقرَ — أي في هذه النارِ العظيمة؟ سؤالٌ من أهلِ الجنّةِ (أو الملائكة) للمجرمين على وجهِ التقريعِ والتوبيخِ والاعتبار «ما سلككم في سقر»؛ ففي هذا بيانُ السؤالِ الموجّهِ للمجرمين عن سببِ دخولهم النار، ليُقِرّوا بأعمالهم التي أوردتهم، فيكون في ذلك عبرةٌ لكلِّ سامع؛ فالسؤالُ عن سببِ العذابِ يدفع إلى اجتنابِ ذلك السبب؛ فاسأل أنت نفسك محاسبًا: ما الأعمالُ التي تُورِد النارَ لأجتنبها؟ وتفقّد نفسك في الصلاةِ والإحسانِ والبعدِ عن الخوضِ والتكذيب؛ وقفوهم إنهم مسؤولون؛ ونادى أصحابُ الجنّةِ أصحابَ النار؛ فمحاسبةُ النفسِ عمّا يُورِد النارَ سبيلُ النجاة؛ فحاسب نفسك، وتفقّد أعمالك، واجتنب ما يُوردها؛ فمن حاسب نفسه واجتنب الموبقاتِ نجا، ومن أهملها ورد سقر؛ فاجعل محاسبةَ النفسِ عمّا يُورِد النارَ دأبك."}},{"n":43,"reflection":{"text":"«قالوا لم نك من المصلين» — قال المجرمون: لم نكن من المصلّين (تركنا الصلاة)؛ ففي هذا بيانُ أنّ تركَ الصلاةِ أوّلُ أسبابِ دخولِ النار؛ فحافظ على الصلاةِ فإنّ تركها من أسبابِ سقر، فالصلاةُ عمودُ الدين وتركها هلاك، فحافظ عليها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المحافظةُ على الصلاةِ والحذرُ من تركِها."},"action":{"text":"تأمّل أوّلَ أسبابِ هلاكهم: قالوا — أي أجاب المجرمون معترفين بأسبابِ عذابهم — لم نك من المصلّين — أي لم نكن نصلّي ولا نعبد الله، تركنا الصلاةَ في الدنيا؛ فجعلوا تركَ الصلاةِ أوّلَ ما اعترفوا به من موجباتِ عذابهم «قالوا لم نك من المصلين»؛ ففي هذا بيانُ أنّ تركَ الصلاةِ من أعظمِ أسبابِ دخولِ النار، وأنّ المجرمين قدّموه في الاعترافِ لعظمِ شأنه؛ فالصلاةُ عمودُ الدين، وتركها من موجباتِ الهلاك؛ فحافظ أنت على الصلاةِ في أوقاتها بخشوعها، وكن من المصلّين، واحذر التهاونَ بها أو تركها؛ فويلٌ للمصلّين الذين هم عن صلاتهم ساهون؛ فخلف من بعدهم خلفٌ أضاعوا الصلاةَ واتّبعوا الشهواتِ فسوف يلقون غيًّا؛ حافظوا على الصلواتِ والصلاةِ الوسطى؛ فتركُ الصلاةِ من أسبابِ سقر، والمحافظةُ عليها سبيلُ النجاة؛ فحافظ عليها، وأقمها، ولا تتهاون بها؛ فمن حافظ على الصلاةِ نجا، ومن تركها ورد سقر؛ فاجعل المحافظةَ على الصلاةِ والحذرَ من تركِها دأبك."}},{"n":44,"reflection":{"text":"«ولم نك نطعم المسكين» — ولم نكن نُطعِم المسكينَ ولا نحضّ عليه (منعنا حقَّ المال)؛ ففي هذا بيانُ أنّ منعَ الإحسانِ للمساكينِ من أسبابِ النار؛ فأطعِم المسكينَ وأحسن إليه، فمنعُ الإحسانِ من أسبابِ سقر، فأطعم وأحسن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إطعامُ المسكينِ والإحسانُ إليه، والحذرُ من منعِ الحقّ."},"action":{"text":"تأمّل ثانيَ أسبابِ هلاكهم: ولم نك نُطعِم المسكينَ — أي لم نكن نُطعِم الفقيرَ المحتاجَ ولا نحضّ على إطعامه، بخلنا بحقوقِ الأموالِ ومنعنا الإحسان؛ فجعلوا تركَ الإحسانِ إلى المساكينِ من موجباتِ عذابهم، بعد تركِ حقِّ الله في الصلاة «ولم نك نطعم المسكين»؛ ففي هذا بيانُ أنّ منعَ الإحسانِ إلى المساكينِ والبخلَ بحقوقِ المالِ من أسبابِ دخولِ النار، وأنّ الدينَ حقٌّ لله (الصلاة) وحقٌّ للخلق (الإطعام)؛ فمنعُ الإحسانِ من موجباتِ الهلاك؛ فأطعِم أنت المسكينَ وأحسن إليه، وأدِّ حقوقَ مالك، وحُضَّ على إطعامِ المحتاجين، ولا تبخل؛ ولا يحضّ على طعامِ المسكين؛ أرأيت الذي يكذّب بالدين فذلك الذي يدعّ اليتيمَ ولا يحضّ على طعامِ المسكين؛ ويطعمون الطعامَ على حبّه مسكينًا ويتيمًا وأسيرًا؛ فالإحسانُ إلى المساكينِ من أسبابِ النجاة، ومنعُه من أسبابِ سقر؛ فأطعِم، وأحسِن، وأدِّ الحقوق؛ فمن أطعم وأحسن نجا، ومن بخل ومنع هلك؛ فاجعل إطعامَ المسكينِ والإحسانَ إليه دأبك."}},{"n":45,"reflection":{"text":"«وكنا نخوض مع الخائضين» — وكنّا نخوض في الباطلِ مع الخائضين فيه (من الاستهزاءِ بالدينِ وتكذيبِ الحقّ)؛ ففي هذا بيانُ أنّ الخوضَ في الباطلِ من أسبابِ النار؛ فاحذر مجالسَ الباطلِ والخوضَ فيها، فالخوضُ مع الخائضين من أسبابِ سقر، فاجتنبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الخوضِ في الباطلِ ومجالسِه."},"action":{"text":"تأمّل ثالثَ أسبابِ هلاكهم: وكنّا نخوض — أي نتحدّث في الباطلِ ونشتغل به — مع الخائضين — أي مع أهلِ الباطلِ الخائضين فيه، فكنّا كلّما غوى غاوٍ غوينا معه، نخوض في تكذيبِ الحقِّ والاستهزاءِ بالدينِ والكلامِ الباطل «وكنا نخوض مع الخائضين»؛ ففي هذا بيانُ أنّ الخوضَ في الباطلِ ومصاحبةَ أهله ومجالستهم من أسبابِ دخولِ النار؛ فالخوضُ في الباطلِ ومجالسةُ أهله من موجباتِ الهلاك؛ فاحذر أنت مجالسَ الباطلِ والخوضَ فيها، ولا تصاحب الخائضين في تكذيبِ الحقِّ والاستهزاءِ بالدين، وقم عنهم إذا خاضوا؛ وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم حتى يخوضوا في حديثٍ غيره؛ وقد نزّل عليكم في الكتابِ أن إذا سمعتم آياتِ الله يُكفَر بها ويُستهزَأ بها فلا تقعدوا معهم؛ والذين لا يشهدون الزور؛ فالخوضُ في الباطلِ ومجالسةُ أهله من أسبابِ سقر، واجتنابُها سبيلُ النجاة؛ فاجتنبها، وأعرض عن الخائضين، ولا تخض معهم؛ فمن اجتنب الباطلَ وأهله سلم، ومن خاض معهم هلك؛ فاجعل اجتنابَ الخوضِ في الباطلِ ومجالسِه دأبك."}},{"n":46,"reflection":{"text":"«وكنا نكذب بيوم الدين» — وكنّا نكذّب بيومِ الجزاءِ والحساب؛ ففي هذا بيانُ أنّ التكذيبَ بالبعثِ رأسُ أسبابِ النار؛ فأيقن بيومِ الدينِ واعمل له، فالتكذيبُ بيومِ الدينِ أصلُ الهلاك، فأيقن به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بيومِ الدينِ والعملُ له، والحذرُ من التكذيبِ به."},"action":{"text":"تأمّل رابعَ أسبابِ هلاكهم وأصلَها: وكنّا نكذّب بيومِ الدين — أي نكذّب بيومِ الجزاءِ والحسابِ والبعث، ننكره ولا نصدّق به؛ وهذا أصلُ فسادهم، فإنّ التكذيبَ بالجزاءِ يحمل على تركِ الطاعةِ وارتكابِ المعاصي «وكنا نكذب بيوم الدين»؛ ففي هذا بيانُ أنّ التكذيبَ بيومِ الدينِ (البعثِ والجزاء) هو رأسُ أسبابِ هلاكهم وأصلُ ما جرّهم إلى تركِ الصلاةِ ومنعِ الإحسانِ والخوضِ في الباطل، فإنّ من كذّب بالجزاءِ استخفّ بالطاعةِ والمعصية؛ فالتكذيبُ بيومِ الدينِ أصلُ الهلاكِ ومنبعُ الشرور؛ فأيقن أنت بيومِ الدينِ يقينًا جازمًا، واعمل له، فإنّ اليقينَ بالجزاءِ يحمل على الطاعةِ ويردع عن المعصية؛ أرأيت الذي يكذّب بالدين؛ ويلٌ يومئذٍ للمكذّبين الذين يكذّبون بيومِ الدين؛ بل يريدون ليفجروا أمامه؛ فالتكذيبُ بيومِ الدينِ أصلُ كلِّ شرّ، واليقينُ به أصلُ كلِّ خير؛ فأيقن به، واعمل له، واحذر التكذيبَ؛ فمن أيقن بالجزاءِ استقام، ومن كذّب به انحلّ وهلك؛ فاجعل اليقينَ بيومِ الدينِ والعملَ له دأبك."}},{"n":47,"reflection":{"text":"«حتى أتانا اليقين» — حتى جاءنا اليقينُ (الموتُ) ونحن على ذلك التكذيبِ والمعصية؛ ففي هذا بيانُ أنهم أصرّوا على الكفرِ حتى الموتِ فلا توبةَ بعده؛ فبادر بالتوبةِ والعملِ قبل مجيءِ اليقين، فالموتُ يقطع بابَ العمل، فبادر قبله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالتوبةِ والعملِ قبل مجيءِ الموت."},"action":{"text":"تأمّل إصرارَهم حتى الموت: حتى أتانا اليقينُ — أي حتى جاءنا الموتُ (سُمّي يقينًا لأنه أمرٌ متيقّنٌ لا شكّ فيه، ولأنه يحصل به اليقينُ بما كان يُكذَّب به) ونحن على ذلك الكفرِ والتكذيبِ والمعصية، فوافانا الموتُ على سوءِ حالنا «حتى أتانا اليقين»؛ ففي هذا بيانُ أنّ هؤلاء المجرمين أصرّوا على تكذيبهم ومعاصيهم حتى أدركهم الموتُ فلا توبةَ بعده ولا استدراك، فكان ذلك سببَ خلودهم في العذاب؛ فالموتُ يقطع بابَ العملِ والتوبة؛ فبادر أنت بالتوبةِ والإيمانِ والعملِ الصالحِ قبل أن يأتيك اليقينُ (الموت)، ولا تسوّف، فإنّ من مات على حالٍ بُعِث عليه؛ واعبد ربّك حتى يأتيك اليقين؛ وأنفقوا من ما رزقناكم من قبلِ أن يأتي أحدكم الموت؛ حتى إذا جاء أحدهم الموتُ قال ربِّ ارجعون؛ فالموتُ نهايةُ مهلةِ العمل، والموفّقُ من بادر قبله؛ فبادر بالتوبةِ والعمل، ولا تسوّف، واغتنم مهلتك؛ فمن بادر قبل الموتِ نجا، ومن سوّف حتى أتاه اليقينُ هلك؛ فاجعل المبادرةَ بالتوبةِ والعملِ قبل الموتِ دأبك."}},{"n":48,"reflection":{"text":"«فما تنفعهم شفاعة الشافعين» — فما تنفع المكذّبين شفاعةُ من يشفع (لو شفع) لأنهم ماتوا على الكفر؛ ففي هذا بيانُ أنّ الشفاعةَ لا تنفع الكافرين؛ فاعمل لتنال الشفاعةَ بالإيمان، فالشفاعةُ لا تنفع من مات كافرًا، فآمن لتنالها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والعملُ لنيلِ الشفاعة، والعلمُ بأنها لا تنفع الكافر."},"action":{"text":"تأمّل حرمانهم من الشفاعة: فما تنفعهم شفاعةُ الشافعين — أي فلا تنفع هؤلاء المكذّبين الذين ماتوا على الكفرِ شفاعةُ أحدٍ من الشافعين لو شفع (من الأنبياءِ والملائكةِ والصالحين)، لأنّ الشفاعةَ لا تكون إلا لمن ارتضى الله من أهلِ التوحيد، وهؤلاء ماتوا كافرين «فما تنفعهم شفاعة الشافعين»؛ ففي هذا بيانُ أنّ الشفاعةَ لا تنفع الكافرين المكذّبين، وأنها إنما تكون لأهلِ الإيمانِ والتوحيدِ بإذنِ الله؛ فالشفاعةُ لا تنفع من مات على الكفر؛ فاعمل أنت لتكون من أهلِ الشفاعةِ بالإيمانِ والتوحيدِ والعملِ الصالح، ولا تكن من الكافرين الذين لا تنفعهم شفاعةُ شافع؛ يومئذٍ لا تنفع الشفاعةُ إلا من أذن له الرحمنُ ورضي له قولًا؛ ولا يشفعون إلا لمن ارتضى؛ ما للظالمين من حميمٍ ولا شفيعٍ يُطاع؛ فالشفاعةُ نعمةٌ لأهلِ التوحيد، محجوبةٌ عن الكافرين؛ فآمن، ووحّد، واعمل، لتكون من أهلها؛ فمن مات مؤمنًا نالته الشفاعةُ بإذنِ الله، ومن مات كافرًا لم تنفعه؛ فاجعل الإيمانَ والعملَ لنيلِ الشفاعةِ دأبك."}}]},{"title":"الإنكارُ على المعرضين عن التذكرةِ والختام","range":[49,56],"theme":"استنكارُ إعراضهم عن القرآن «فما لهم عن التذكرة معرضين كأنهم حمر مستنفرة فرت من قسورة»، وتعنّتِهم «أن يؤتى صحفا منشرة»، وأنّ أصلَه عدمُ خوفِ الآخرة «كلا بل لا يخافون الآخرة»، وأنّ القرآنَ تذكرة «فمن شاء ذكره»، والختامِ بمشيئةِ الله وأهليّتِه «وما يذكرون إلا أن يشاء الله هو أهل التقوى وأهل المغفرة»","verses":[{"n":49,"reflection":{"text":"«فما لهم عن التذكرة معرضين» — فأيُّ شيءٍ لهؤلاء المكذّبين حالَ كونهم مُعرِضين عن التذكرةِ (القرآنِ والموعظة)؟ ففي هذا إنكارٌ على إعراضهم عن القرآنِ مع وضوحِ حجّته؛ فأقبل على التذكرةِ ولا تُعرِض عنها، فالإعراضُ عن القرآنِ عجبٌ مستنكَر، فأقبل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على القرآنِ والتذكرة، والحذرُ من الإعراضِ عنها."},"action":{"text":"تأمّل استنكارَ إعراضهم: فما لهم — أي فأيُّ شيءٍ لهؤلاء المكذّبين، وما الذي عرض لهم — عن التذكرةِ — أي عن هذا القرآنِ والموعظةِ التي تُذكّرهم وتنفعهم — معرضين — أي حالَ كونهم مُعرِضين منصرفين عنها؟ استفهامُ إنكارٍ وتعجّبٍ من إعراضهم عمّا فيه نجاتهم مع وضوحِ حجّته «فما لهم عن التذكرة معرضين»؛ ففي هذا بيانُ الإنكارِ والتعجّبِ من إعراضِ المكذّبين عن القرآنِ والتذكرةِ النافعة، مع أنها تدعوهم إلى ما فيه سعادتهم؛ فالإعراضُ عن القرآنِ مع وضوحِ حقّه عجبٌ مستنكَر؛ فأقبل أنت على القرآنِ والتذكرة، واستمع لها، واتّعظ بها، ولا تكن من المعرضين عنها؛ وكم من آيةٍ في السماواتِ والأرضِ يمرّون عليها وهم عنها معرضون؛ ومن أظلمُ ممّن ذُكِّر بآياتِ ربّه فأعرض عنها؛ وإذا ذُكِّروا لا يذكرون؛ فالإعراضُ عن القرآنِ والتذكرةِ خسرانٌ مستنكَر، والإقبالُ عليها سبيلُ الهدى؛ فأقبل عليها، واتّعظ، ولا تُعرِض؛ فمن أقبل على التذكرةِ اهتدى، ومن أعرض عنها ضلّ؛ فاجعل الإقبالَ على القرآنِ والحذرَ من الإعراضِ دأبك."}},{"n":50,"reflection":{"text":"«كأنهم حمر مستنفرة» — كأنهم في نفارهم عن الحقِّ حمرٌ وحشيّةٌ نافرةٌ شديدةُ الفرار؛ ففي هذا تشبيهُ نفورِ المكذّبين عن القرآنِ بنفورِ الحُمرِ الوحشيّة؛ فأقبل على الحقِّ ولا تنفر منه نفورَ الحُمر، فالنفورُ عن الحقِّ حالُ البهائمِ لا العقلاء، فأقبل عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الحقِّ بعقلٍ، والحذرُ من النفورِ عنه."},"action":{"text":"تأمّل تشبيهَ نفورهم: كأنهم — في إعراضهم ونفورهم عن التذكرة — حمرٌ مستنفرةٌ — أي حُمرٌ وحشيّةٌ (حميرُ الوحش) نافرةٌ شديدةُ الفرارِ والنِّفار «كأنهم حمر مستنفرة»؛ ففي هذا بيانُ تشبيهِ حالِ المكذّبين في نفورهم الشديدِ عن القرآنِ والحقّ بحالِ الحُمرِ الوحشيّةِ النافرة، تحقيرًا لهم وذمًّا لنفورهم عمّا فيه نجاتهم؛ فالنفورُ عن الحقِّ حالُ البهائمِ النافرةِ لا حالُ العقلاءِ المميّزين؛ فأقبل أنت على الحقِّ بعقلك وتمييزك، ولا تنفر عنه نفورَ الحُمرِ الوحشيّة، بل استمع وتدبّر واتّبع؛ أولئك كالأنعامِ بل هم أضلّ؛ ومثلُ الذين كفروا كمثلِ الذي ينعق بما لا يسمع؛ صمٌّ بكمٌ عميٌ فهم لا يعقلون؛ فالنفورُ عن الحقِّ حالُ البهائم، والإقبالُ عليه حالُ العقلاء؛ فأقبل على الحقِّ، وتدبّره، ولا تنفر عنه؛ فمن أقبل على الحقِّ بعقله اهتدى، ومن نفر عنه كالبهيمةِ ضلّ؛ فاجعل الإقبالَ على الحقِّ بعقلٍ دأبك."}},{"n":51,"reflection":{"text":"«فرت من قسورة» — فرّت تلك الحُمرُ من أسدٍ (أو رامٍ صائد) فزعًا؛ ففي هذا تمامُ التشبيهِ في شدّةِ فرارِ المكذّبين عن الحقّ؛ فلا تفرّ من الحقِّ فرارَ الفزعِ من الأسد، بل افزع إليه، فالفرارُ من الحقِّ حمقٌ، فأقبل عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الحقِّ لا الفرارُ منه."},"action":{"text":"تأمّل تمامَ التشبيه: فرّت من قسورةٍ — أي فرّت تلك الحُمرُ الوحشيّةُ من قسورةٍ، وهو الأسدُ (أو الرُّماةُ والصيّادون)، فزعًا وذعرًا؛ فشُبِّه شدّةُ فرارِ المكذّبين عن الحقِّ بشدّةِ فرارِ الحُمرِ الوحشيّةِ من الأسد «فرت من قسورة»؛ ففي هذا تمامُ بيانِ تشبيهِ نفورِ المكذّبين عن القرآن، فهم في شدّةِ إعراضهم كحُمرٍ وحشيّةٍ فرّت مذعورةً من أسد، وهذا غايةُ الذمِّ لنفورهم عمّا فيه حياتهم؛ فالفرارُ من الحقِّ (الذي هو النجاة) فرارَ الفزعِ حمقٌ وضلال؛ فلا تفرّ أنت من الحقِّ والقرآنِ فرارَ المذعور، بل افزع إليه وأقبل عليه فإنه نجاتك؛ ففروا إلى الله؛ يقولون لو أنّ لنا كرّةً فنكون من المؤمنين؛ وإذا قيل لهم تعالوا يستغفر لكم رسولُ الله لوّوا رؤوسهم؛ فالفرارُ من الحقِّ هلاك، والفزعُ إليه نجاة؛ فأقبل عليه، وافزع إليه، ولا تفرّ منه؛ فمن أقبل على الحقِّ نجا، ومن فرّ منه هلك؛ فاجعل الإقبالَ على الحقِّ لا الفرارَ منه دأبك."}},{"n":52,"reflection":{"text":"«بل يريد كل امرئ منهم أن يؤتى صحفا منشرة» — بل يريد كلُّ واحدٍ منهم أن يُؤتى كتبًا منشورةً من الله خاصّةً به (تعنّتًا واقتراحًا)؛ ففي هذا بيانُ تعنّتِ المكذّبين واقتراحهم على الله؛ فلا تتعنّت على الله باقتراحِ الآيات، بل اقبل ما جاءك من الحقّ، فالتعنّتُ على الله كبرٌ وعناد، فاقبل الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ بلا تعنّت، والحذرُ من الاقتراحِ على الله."},"action":{"text":"تأمّل تعنّتهم: بل يريد كلُّ امرئٍ منهم — أي من هؤلاء المكذّبين — أن يُؤتى صحفًا منشّرةً — أي كتبًا مفتوحةً منشورةً من الله ينزل بها المَلَكُ إلى كلِّ واحدٍ منهم خاصّةً، تأمره باتّباعِ محمدٍ، تعنّتًا واقتراحًا وتكبّرًا؛ فلم يكفهم ما جاء به الرسولُ من الآيات «بل يريد كل امرئ منهم أن يؤتى صحفا منشرة»؛ ففي هذا بيانُ تعنّتِ المكذّبين واقتراحهم على الله ما لا يكون، تكبّرًا وعنادًا، إذ طلب كلُّ واحدٍ منهم أن يُنزَّل عليه كتابٌ خاصٌّ به؛ فالتعنّتُ على الله والاقتراحُ عليه من الكبرِ والعناد؛ فاقبل أنت الحقَّ الذي جاءك بلا تعنّتٍ ولا اقتراحِ آياتٍ على الله، فما جاء به الرسولُ كافٍ لمن أراد الهدى؛ وقالوا لن نؤمن لك حتى تفجّر لنا من الأرضِ ينبوعًا؛ أو تأتيَ بالله والملائكةِ قبيلًا؛ وقال الذين لا يرجون لقاءنا لولا أُنزِل علينا الملائكةُ أو نرى ربّنا لقد استكبروا في أنفسهم؛ فالتعنّتُ على الله واقتراحُ الآياتِ كبرٌ وصدٌّ عن الحقّ؛ فاقبل الحقّ، ولا تتعنّت، ولا تقترح على الله؛ فمن قبل الحقَّ بلا تعنّتٍ اهتدى، ومن تعنّت واقترح ضلّ؛ فاجعل قبولَ الحقِّ بلا تعنّتٍ دأبك."}},{"n":53,"reflection":{"text":"«كلا بل لا يخافون الآخرة» — حقًّا، ليس السببُ ما زعموا، بل لأنهم لا يخافون الآخرةَ وعذابها (فلذلك أعرضوا)؛ ففي هذا بيانُ أنّ أصلَ إعراضِ المكذّبين عدمُ خوفِ الآخرة؛ فاخف الآخرةَ يحملك خوفُها على قبولِ الحقِّ والعمل، فعدمُ خوفِ الآخرةِ أصلُ الإعراض، فاخفها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"خوفُ الآخرةِ الحاملُ على قبولِ الحقِّ والعمل."},"action":{"text":"تأمّل أصلَ إعراضهم: كلّا — أي حقًّا، وردعًا لهم عمّا اقترحوه، ليس الأمرُ كما زعموا من حاجتهم إلى صحفٍ منشّرة — بل لا يخافون الآخرةَ — أي بل السببُ الحقيقيُّ لإعراضهم وتعنّتهم أنهم لا يخافون الآخرةَ وحسابها وعذابها، فلو خافوها لآمنوا واتّبعوا «كلا بل لا يخافون الآخرة»؛ ففي هذا بيانُ أنّ أصلَ إعراضِ المكذّبين عن الحقِّ وتعنّتهم هو عدمُ خوفهم من الآخرة، فإنّ الخوفَ من الآخرةِ يحمل على قبولِ الحقِّ والعملِ الصالح، وعدمَه يحمل على الإعراضِ والتكذيب؛ فخوفُ الآخرةِ أصلُ الاستقامة، وعدمُه أصلُ الإعراض؛ فاخف أنت الآخرةَ وحسابها وعذابها، فإنّ خوفها يحملك على قبولِ الحقِّ والاستقامةِ والعمل؛ إنما تنذر من اتّبع الذكرَ وخشي الرحمنَ بالغيب؛ ومن خاف مقامَ ربّه ونهى النفسَ عن الهوى فإنّ الجنّةَ هي المأوى؛ وأمّا من خاف مقامَ ربّه جنّتان؛ فخوفُ الآخرةِ يحمل على الهدى، وعدمُه يحمل على الإعراض؛ فاخفها، واعمل لها، ولا تغفل عنها؛ فمن خاف الآخرةَ اهتدى وعمل، ومن أمنها أعرض وهلك؛ فاجعل خوفَ الآخرةِ الحاملِ على العملِ دأبك."}},{"n":54,"reflection":{"text":"«كلا إنه تذكرة» — حقًّا، إنّ هذا القرآنَ تذكرةٌ وعظةٌ (لمن أراد أن يتذكّر)؛ ففي هذا تقريرُ أنّ القرآنَ موعظةٌ كافيةٌ لمن اتّعظ؛ فاتّعظ بالقرآنِ فإنه تذكرةٌ لك، فالقرآنُ تذكرةٌ كافيةٌ فاتّعظ بها، فتذكّر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالقرآنِ واتّخاذُه تذكرة."},"action":{"text":"تأمّل كفايةَ التذكرة: كلّا — أي حقًّا، وردعًا لهم عن تعنّتهم — إنه — أي هذا القرآنَ — تذكرةٌ — أي عظةٌ وتذكيرٌ كافٍ لمن أراد أن يتذكّر ويتّعظ، لا يحتاج معه إلى صحفٍ منشّرةٍ ولا آياتٍ مقترحة «كلا إنه تذكرة»؛ ففي هذا بيانُ أنّ القرآنَ في نفسه تذكرةٌ وموعظةٌ كافيةٌ شافيةٌ لمن أراد الهدى، وردٌّ على تعنّتِ المكذّبين الذين طلبوا غيره؛ فالقرآنُ تذكرةٌ كافيةٌ لمن اتّعظ؛ فاتّعظ أنت بالقرآن، واتّخذه تذكرةً وموعظة، وتدبّره وتذكّر به، ولا تطلب سواه؛ فذكّر بالقرآنِ من يخاف وعيد؛ وإنه لتذكرةٌ للمتّقين؛ ونُنزّل من القرآنِ ما هو شفاءٌ ورحمة؛ فالقرآنُ تذكرةٌ كافية، والموفّقُ من اتّعظ بها؛ فاتّعظ به، وتذكّر، واعمل بمقتضاه؛ فمن اتّعظ بالقرآنِ اهتدى، ومن أعرض عنه وطلب سواه ضلّ؛ فاجعل الاتّعاظَ بالقرآنِ واتّخاذَه تذكرةً دأبك."}},{"n":55,"reflection":{"text":"«فمن شاء ذكره» — فمن شاء ذكر القرآنَ واتّعظ به وانتفع (بمشيئةٍ مندرجةٍ تحت مشيئةِ الله)؛ ففي هذا بيانُ أنّ التذكّرَ باختيارِ العبدِ ورغبته؛ فبادر بذكرِ القرآنِ والاتّعاظِ به، فبابُ التذكّرِ مفتوحٌ لمن شاء، فبادر إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بذكرِ القرآنِ والاتّعاظِ به."},"action":{"text":"تأمّل بابَ التذكّر: فمن شاء ذكره — أي فمن شاء من الناسِ ذكر القرآنَ واتّعظ به وحفظه وانتفع بمواعظه، فالبابُ مفتوحٌ والاختيارُ للعبدِ في أن يتذكّر أو يُعرِض، ومشيئتُه مندرجةٌ تحت مشيئةِ الله «فمن شاء ذكره»؛ ففي هذا بيانُ أنّ التذكّرَ بالقرآنِ والانتفاعَ به متعلّقٌ بمشيئةِ العبدِ ورغبته، فمن أراد الخيرَ ذكره واتّعظ به؛ فبابُ التذكّرِ مفتوحٌ لمن شاء أن يسلكه؛ فبادر أنت بذكرِ القرآنِ والاتّعاظِ به والعملِ بمقتضاه، ولا تحرم نفسك وقد فُتِح لك البابُ، واغتنم إرادتك للخيرِ فاسلكها؛ إنّ هذه تذكرةٌ فمن شاء اتّخذ إلى ربّه سبيلًا؛ فمن شاء منكم أن يتقدّم أو يتأخّر؛ فذكّر إن نفعت الذكرى سيذّكّر من يخشى؛ فالتذكّرُ باختيارِ العبد، والموفّقُ من بادر إليه؛ فبادر بذكرِ القرآنِ والاتّعاظِ به، ولا تسوّف؛ فمن ذكره واتّعظ اهتدى، ومن أعرض ضلّ؛ فاجعل المبادرةَ بذكرِ القرآنِ والاتّعاظِ به دأبك."}},{"n":56,"reflection":{"text":"«وما يذكرون إلا أن يشاء الله هو أهل التقوى وأهل المغفرة» — وما يتذكّرون إلا بمشيئةِ الله وتوفيقه، هو سبحانه أهلٌ أن يُتَّقى ويُخاف، وأهلٌ أن يغفر لمن اتّقاه وتاب؛ ففي هذا بيانُ أنّ الهدايةَ بمشيئةِ الله وتوفيقه، وأنه أهلُ التقوى والمغفرة؛ فاسأل الله التوفيقَ للذكرى، واتّقه وارجُ مغفرته، فهو أهلٌ أن يُتَّقى ويَغفِر، فاتّقه وارجُه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"افتقارُ العبدِ إلى توفيقِ الله، وتقواه ورجاءُ مغفرته."},"action":{"text":"تأمّل خاتمةَ السورة: وما يذكرون إلا أن يشاء الله — أي وما يتذكّر هؤلاء ولا ينتفعون بالقرآنِ إلا بمشيئةِ الله وتوفيقه وهدايته، فالمشيئةُ لله، والعبدُ مفتقرٌ إلى توفيقه — هو أهلُ التقوى — أي هو سبحانه أهلٌ وحقيقٌ أن يُتَّقى ويُخاف ويُطاع فلا يُعصى، لعظمته وجلاله — وأهلُ المغفرة — أي وأهلٌ أن يغفر لمن اتّقاه وآمن به وتاب إليه، لسعةِ رحمته وكرمه «وما يذكرون إلا أن يشاء الله هو أهل التقوى وأهل المغفرة»؛ ففي هذا بيانُ أنّ هدايةَ العبدِ وتذكّرَه بمشيئةِ الله وتوفيقه، فالعبدُ مفتقرٌ إليه في كلِّ خير، وأنّ الله جمع بين كونه أهلًا أن يُتَّقى (لجلاله) وأهلًا أن يَغفِر (لرحمته)، فيُرجى مع الخوفِ منه؛ فالتوفيقُ بيدِ الله، وهو أهلُ التقوى والمغفرة؛ فاسأل أنت الله التوفيقَ للذكرى والهدى والعمل، ولا تتّكل على حولك، واتّقه كما هو أهله، وارجُ مغفرته كما هو أهلها، فاجمع بين خوفه ورجائه؛ وما تشاؤون إلا أن يشاء الله؛ نبّئ عبادي أني أنا الغفورُ الرحيم وأنّ عذابي هو العذابُ الأليم؛ اعلموا أنّ الله شديدُ العقابِ وأنّ الله غفورٌ رحيم؛ فالعبدُ مفتقرٌ إلى توفيقِ الله، والله أهلٌ أن يُتَّقى ويَغفِر؛ فاسأله التوفيق، واتّقه، وارجُ مغفرته؛ فمن اتّقاه ورجاه ووُفِّق نجا، ومن اتّكل على نفسه أو أمِن مكره خسر؛ فاجعل افتقارَك إلى توفيقِ الله وتقواه ورجاءَ مغفرته دأبك."}}]}],"coverage":{"covered":56,"total":56}};
